	mode := os.Args[1]
	w, _ := strconv.Atoi(os.Args[2])
	h, _ := strconv.Atoi(os.Args[3])
	out := os.Args[4]
	var img image.Image
	switch mode {
	case "grad":
		m := image.NewNRGBA(image.Rect(0, 0, w, h))
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				m.Set(x, y, color.NRGBA{uint8(x * 255 / max(w-1, 1)), uint8(y * 255 / max(h-1, 1)), uint8((x + y) * 7), 255})
			}
		}
		img = m
	case "alpha":
		// alpha gradient horizontally, color vertical
		m := image.NewNRGBA(image.Rect(0, 0, w, h))
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				a := uint8(x * 255 / max(w-1, 1))
				m.Set(x, y, color.NRGBA{200, uint8(y * 255 / max(h-1, 1)), 100, a})
			}
		}
