		m := image.NewNRGBA(image.Rect(0, 0, w, h))
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				m.Set(x, y, color.NRGBA{uint8(r), uint8(g), uint8(b), uint8(a)})
			}
		}
		img = m
	case "checker":
		m := image.NewNRGBA(image.Rect(0, 0, w, h))
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				if (x+y)%2 == 0 {
					m.Set(x, y, color.NRGBA{255, 255, 255, 255})
				} else {
					m.Set(x, y, color.NRGBA{0, 0, 0, 255})
				}
			}
		}
		img = m
	case "gray":
		m := image.NewGray(image.Rect(0, 0, w, h))
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				m.Set(x, y, color.Gray{uint8((x*255/max(w-1,1) + y*255/max(h-1,1)) / 2)})
			}
		}
		img = m
	case "hgrad":
		// horizontal gradient of gray levels
		m := image.NewNRGBA(image.Rect(0, 0, w, h))
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				v := uint8(x * 255 / max(w-1, 1))
				m.Set(x, y, color.NRGBA{v, v, v, 255})
			}
		}
		img = m
	}
