# extract pixel rows from non-dither output: prints one line per pixel row: "r,g,b r,g,b ..."
import sys, re
data = open(sys.argv[1], 'rb').read().decode('utf-8')
lines = [l for l in data.split('\n') if l]
pat = re.compile(r'\x1b\[48;2;(\d+);(\d+);(\d+)m\x1b\[38;2;(\d+);(\d+);(\d+)m(.)')
for line in lines:
    cells = pat.findall(line)
    if not cells: 
        print("??", line[:80]); continue
    print(' '.join(f"{c[0]},{c[1]},{c[2]}" for c in cells))
    print(' '.join(f"{c[3]},{c[4]},{c[5]}" for c in cells))
