module cand

go 1.21
EOF
cat > main.go <<'EOF'
package main

import (
	"fmt"
	"image"
	"image/color"
	"image/draw"
	_ "image/gif"
	_ "image/jpeg"
	_ "image/png"
	"math"
	"os"
	"strconv"
)

type Filter struct {
	Support float64
	Kernel  func(float64) float64
}

func sinc(x float64) float64 {
	if x == 0 {
		return 1
	}
	return math.Sin(math.Pi*x) / (math.Pi * x)
}

func bcspline(x, b, c float64) float64 {
	var y float64
	x = math.Abs(x)
	if x < 1.0 {
		y = ((12-9*b-6*c)*x*x*x + (-18+12*b+6*c)*x*x + (6 - 2*b)) / 6
	} else if x < 2.0 {
		y = ((-b-6*c)*x*x*x + (6*b+30*c)*x*x + (-12*b-48*c)*x + (8*b + 24*c)) / 6
	}
	return y
}

var filters = map[string]Filter{
	"box": {0.5, func(x float64) float64 {
		x = math.Abs(x)
		if x <= 0.5 {
			return 1
		}
		return 0
	}},
	"linear": {1.0, func(x float64) float64 {
		x = math.Abs(x)
		if x < 1 {
			return 1 - x
		}
		return 0
	}},
	"hermite": {1.0, func(x float64) float64 { return bcspline(x, 0, 0) }},
	"mitchell": {2.0, func(x float64) float64 { return bcspline(x, 1.0/3.0, 1.0/3.0) }},
	"catrom": {2.0, func(x float64) float64 { return bcspline(x, 0, 0.5) }},
	"bspline": {2.0, func(x float64) float64 { return bcspline(x, 1, 0) }},
	"lanczos": {3.0, func(x float64) float64 {
		x = math.Abs(x)
		if x < 3 {
			return sinc(x) * sinc(x/3)
		}
		return 0
	}},
	"lanczos2": {2.0, func(x float64) float64 {
		x = math.Abs(x)
		if x < 2 {
			return sinc(x) * sinc(x/2)
		}
		return 0
	}},
	"hann": {3.0, func(x float64) float64 {
		x = math.Abs(x)
		if x < 3 {
			return sinc(x) * (0.5 + 0.5*math.Cos(math.Pi*x/3))
		}
		return 0
	}},
	"hamming": {3.0, func(x float64) float64 {
		x = math.Abs(x)
		if x < 3 {
			return sinc(x) * (0.54 + 0.46*math.Cos(math.Pi*x/3))
		}
		return 0
	}},
	"blackman": {3.0, func(x float64) float64 {
		x = math.Abs(x)
		if x < 3 {
			return sinc(x) * (0.42 - 0.5*math.Cos(math.Pi*x/3+math.Pi) + 0.08*math.Cos(2*math.Pi*x/3))
		}
		return 0
	}},
	"bartlett": {3.0, func(x float64) float64 {
		x = math.Abs(x)
		if x < 3 {
			return sinc(x) * (3 - x) / 3
		}
		return 0
	}},
	"welch": {3.0, func(x float64) float64 {
		x = math.Abs(x)
		if x < 3 {
			return sinc(x) * (1 - x*x/9)
		}
		return 0
	}},
	"cosine": {3.0, func(x float64) float64 {
		x = math.Abs(x)
		if x < 3 {
			return sinc(x) * math.Cos(math.Pi/2*x/3)
		}
		return 0
	}},
	"gaussian": {2.0, func(x float64) float64 {
		x = math.Abs(x)
		if x < 2 {
			return math.Exp(-2 * x * x)
		}
		return 0
	}},
}

type iw struct {
	idx int
	w   float64
}

func weights(dst, src int, f Filter) [][]iw {
	du := float64(src) / float64(dst)
	scale := du
	if scale < 1 {
		scale = 1
	}
	ru := math.Ceil(scale * f.Support)
	out := make([][]iw, dst)
	for v := 0; v < dst; v++ {
		fu := (float64(v)+0.5)*du - 0.5
		begin := int(math.Ceil(fu - ru))
		if begin < 0 {
			begin = 0
		}
		end := int(math.Floor(fu + ru))
		if end > src-1 {
			end = src - 1
		}
		var sum float64
		var tmp []iw
		for u := begin; u <= end; u++ {
			w := f.Kernel((float64(u) - fu) / scale)
			if w != 0 {
				sum += w
				tmp = append(tmp, iw{u, w})
			}
		}
		if sum != 0 {
			for i := range tmp {
				tmp[i].w /= sum
			}
		}
		out[v] = tmp
	}
	return out
}

func clamp(v float64) uint8 {
	return uint8(math.Min(math.Max(v+0.5, 0), 255))
}

func toNRGBA(img image.Image) *image.NRGBA {
	b := img.Bounds()
	dst := image.NewNRGBA(image.Rect(0, 0, b.Dx(), b.Dy()))
	draw.Draw(dst, dst.Bounds(), img, b.Min, draw.Src)
	return dst
}

func resizeH(src *image.NRGBA, w int, f Filter) *image.NRGBA {
	sw, sh := src.Rect.Dx(), src.Rect.Dy()
	dst := image.NewNRGBA(image.Rect(0, 0, w, sh))
	ws := weights(w, sw, f)
	for y := 0; y < sh; y++ {
		for x := 0; x < w; x++ {
			var r, g, b, a float64
			for _, e := range ws[x] {
				i := y*src.Stride + e.idx*4
				s := src.Pix[i : i+4]
				aw := float64(s[3]) * e.w
				r += float64(s[0]) * aw
				g += float64(s[1]) * aw
				b += float64(s[2]) * aw
				a += aw
			}
			if a != 0 {
				j := y*dst.Stride + x*4
				dst.Pix[j] = clamp(r / a)
				dst.Pix[j+1] = clamp(g / a)
				dst.Pix[j+2] = clamp(b / a)
				dst.Pix[j+3] = clamp(a)
			}
		}
	}
	return dst
}

func resizeV(src *image.NRGBA, h int, f Filter) *image.NRGBA {
	sw, sh := src.Rect.Dx(), src.Rect.Dy()
	dst := image.NewNRGBA(image.Rect(0, 0, sw, h))
	ws := weights(h, sh, f)
	for x := 0; x < sw; x++ {
		for y := 0; y < h; y++ {
			var r, g, b, a float64
			for _, e := range ws[y] {
				i := e.idx*src.Stride + x*4
				s := src.Pix[i : i+4]
				aw := float64(s[3]) * e.w
				r += float64(s[0]) * aw
				g += float64(s[1]) * aw
				b += float64(s[2]) * aw
				a += aw
			}
			if a != 0 {
				j := y*dst.Stride + x*4
