				dst.Pix[j+2] = clamp(b / a)
				dst.Pix[j+3] = clamp(a)
			}
		}
	}
	return dst
}

func resize(src *image.NRGBA, w, h int, f Filter) *image.NRGBA {
	sw, sh := src.Rect.Dx(), src.Rect.Dy()
	if w == sw && h == sh {
