        sols=[]
        A=4.0
        while A<=12.0:
            lo=-1e9; hi=1e9
            for v in range(256):
                x=v/denom*A
                lo=max(lo, exp(v)-x); hi=min(hi, exp(v)+1-x)
            if lo<hi:
                sols.append((round(A,3), round(lo,4), round(hi,4)))
            A+=0.001
        if sols:
            print(name, denom, "A range:", sols[0], "...", sols[-1], len(sols))
        else:
            print(name, denom, "no solution")
