	}
	radius := math.Ceil(scale * lanczosSupport)
	taps := make([][]tap, dstSize)
	for d := 0; d < dstSize; d++ {
		center := (float64(d)+0.5)*ratio - 0.5
		lo := int(math.Ceil(center - radius))
		if lo < 0 {
			lo = 0
		}
		hi := int(math.Floor(center + radius))
		if hi > srcSize-1 {
			hi = srcSize - 1
		}
		var list []tap
		var sum float64
		for s := lo; s <= hi; s++ {
			w := lanczosKernel((float64(s) - center) / scale)
			if w != 0 {
				sum += w
				list = append(list, tap{s, w})
			}
		}
		if sum != 0 {
			for i := range list {
				list[i].weight /= sum
			}
		}
		taps[d] = list
	}
	return taps
}

func clamp8(v float64) uint8 {
	v += 0.5
	if v < 0 {
		return 0
	}
	if v > 255 {
		return 255
	}
	return uint8(v)
}

func resampleHorizontal(src *image.NRGBA, dstW int) *image.NRGBA {
	srcW, srcH := src.Rect.Dx(), src.Rect.Dy()
	dst := image.NewNRGBA(image.Rect(0, 0, dstW, srcH))
	taps := buildTaps(dstW, srcW)
	for y := 0; y < srcH; y++ {
		row := src.Pix[y*src.Stride : y*src.Stride+srcW*4]
		for x := 0; x < dstW; x++ {
			var r, g, b, a float64
			for _, t := range taps[x] {
				p := row[t.index*4 : t.index*4+4]
				aw := float64(p[3]) * t.weight
				r += float64(p[0]) * aw
				g += float64(p[1]) * aw
				b += float64(p[2]) * aw
				a += aw
			}
			if a != 0 {
				o := y*dst.Stride + x*4
				dst.Pix[o+0] = clamp8(r / a)
				dst.Pix[o+1] = clamp8(g / a)
				dst.Pix[o+2] = clamp8(b / a)
				dst.Pix[o+3] = clamp8(a)
			}
		}
	}
	return dst
}

func resampleVertical(src *image.NRGBA, dstH int) *image.NRGBA {
	srcW, srcH := src.Rect.Dx(), src.Rect.Dy()
	dst := image.NewNRGBA(image.Rect(0, 0, srcW, dstH))
	taps := buildTaps(dstH, srcH)
	for x := 0; x < srcW; x++ {
		for y := 0; y < dstH; y++ {
			var r, g, b, a float64
			for _, t := range taps[y] {
				i := t.index*src.Stride + x*4
				p := src.Pix[i : i+4]
				aw := float64(p[3]) * t.weight
				r += float64(p[0]) * aw
				g += float64(p[1]) * aw
				b += float64(p[2]) * aw
				a += aw
			}
			if a != 0 {
				o := y*dst.Stride + x*4
				dst.Pix[o+0] = clamp8(r / a)
				dst.Pix[o+1] = clamp8(g / a)
				dst.Pix[o+2] = clamp8(b / a)
				dst.Pix[o+3] = clamp8(a)
			}
		}
	}
	return dst
}

// resizeTo scales src to exactly w x h.
func resizeTo(src *image.NRGBA, w, h int) *image.NRGBA {
	if w <= 0 || h <= 0 {
		return image.NewNRGBA(image.Rect(0, 0, 0, 0))
	}
	srcW, srcH := src.Rect.Dx(), src.Rect.Dy()
	if srcW <= 0 || srcH <= 0 {
		return image.NewNRGBA(image.Rect(0, 0, 0, 0))
	}
	if w == srcW && h == srcH {
		return src
	}
	out := src
	if w != srcW {
		out = resampleHorizontal(out, w)
	}
	if h != srcH {
		out = resampleVertical(out, h)
	}
	return out
}

// fitInto scales src down (never up) so that it fits inside w x h while
// keeping the aspect ratio.
func fitInto(src *image.NRGBA, w, h int) *image.NRGBA {
	if w <= 0 || h <= 0 {
		return image.NewNRGBA(image.Rect(0, 0, 0, 0))
	}
	srcW, srcH := src.Rect.Dx(), src.Rect.Dy()
	if srcW <= 0 || srcH <= 0 {
		return image.NewNRGBA(image.Rect(0, 0, 0, 0))
	}
	if srcW <= w && srcH <= h {
		return src
	}
	srcAspect := float64(srcW) / float64(srcH)
	boxAspect := float64(w) / float64(h)
	var nw, nh int
	if srcAspect > boxAspect {
		nw = w
		nh = int(float64(nw) / srcAspect)
	} else {
		nh = h
		nw = int(float64(nh) * srcAspect)
	}
	return resizeTo(src, nw, nh)
}

// cropCenter returns the centred w x h sub-image of src as a new image.
func cropCenter(src *image.NRGBA, w, h int) *image.NRGBA {
	srcW, srcH := src.Rect.Dx(), src.Rect.Dy()
	x0 := (srcW - w) / 2
	y0 := (srcH - h) / 2
	dst := image.NewNRGBA(image.Rect(0, 0, w, h))
	for y := 0; y < h; y++ {
		si := (y0+y)*src.Stride + x0*4
		copy(dst.Pix[y*dst.Stride:y*dst.Stride+w*4], src.Pix[si:si+w*4])
	}
	return dst
}

// fillInto scales src so that it covers w x h and crops the centre.
func fillInto(src *image.NRGBA, w, h int) *image.NRGBA {
	if w <= 0 || h <= 0 {
		return image.NewNRGBA(image.Rect(0, 0, 0, 0))
	}
	srcW, srcH := src.Rect.Dx(), src.Rect.Dy()
	if srcW <= 0 || srcH <= 0 {
		return image.NewNRGBA(image.Rect(0, 0, 0, 0))
	}
	if srcW == w && srcH == h {
		return src
	}
	srcAspect := float64(srcW) / float64(srcH)
	dstAspect := float64(w) / float64(h)
	var tw, th int
	if srcAspect < dstAspect {
		tw = w
		th = int(float64(tw) / srcAspect)
	} else {
		th = h
		tw = int(float64(th) * srcAspect)
	}
	if tw < w {
		tw = w
	}
	if th < h {
		th = h
	}
	tmp := resizeTo(src, tw, th)
	return cropCenter(tmp, w, h)
}
EOF
echo ok

