package main

import (
	"errors"
	"image"
	"image/color"
	"strings"
)

// Scale modes.
const (
	scaleResize = iota
	scaleFill
	scaleFit
)

// Dithering modes.
const (
	ditherNone = iota
	ditherBlocks
	ditherChars
)

var errTooSmall = errors.New("ANSImage: height or width must be >=2")

// rgb is a fully opaque colour.
type rgb struct{ r, g, b uint8 }

// ansiCanvas holds the colour samples that will be turned into terminal
// cells. In classic mode every sample is one image pixel (two samples per
// terminal row); in dithering mode every sample is the average of a 4x8
// block and maps to exactly one terminal cell.
type ansiCanvas struct {
	w, h   int
	cells  [][]rgb
	matte  rgb
	dither int
	noBG   bool
}

const (
	blockW = 4
	blockH = 8
)

var shadeBlocks = []rune{' ', '░', '▒', '▓', '█'}
var shadeBlockLimits = []uint8{49, 101, 153, 205}

var shadeChars = []rune{' ', '.', ':', ';', '+', '=', 'x', 'X', '$', '&', '#'}
var shadeCharLimits = []uint8{24, 47, 70, 93, 116, 139, 162, 185, 208, 231}

// blend composites a non-premultiplied colour over an opaque matte using
// 16-bit "over" arithmetic.
func blend(c color.NRGBA, m rgb) rgb {
	r, g, b, a := c.RGBA()
	inv := (0xffff - a) * 0x101
	return rgb{
		uint8((r + uint32(m.r)*inv/0xffff) >> 8),
		uint8((g + uint32(m.g)*inv/0xffff) >> 8),
		uint8((b + uint32(m.b)*inv/0xffff) >> 8),
	}
}

// buildCanvas scales img according to the requested mode and samples it.
func buildCanvas(img image.Image, rows, cols int, matte rgb, scale, dither int, noBG bool) (*ansiCanvas, error) {
	bw, bh := 1, 2
	if dither != ditherNone {
		bw, bh = blockW, blockH
	}
	targetW := cols * bw
	targetH := (rows + 1) * bh

	src := toNRGBA(img)
	var scaled *image.NRGBA
	switch scale {
	case scaleFill:
		scaled = fillInto(src, targetW, targetH)
	case scaleFit:
		scaled = fitInto(src, targetW, targetH)
	default:
		scaled = resizeTo(src, targetW, targetH)
	}

	pw, ph := scaled.Rect.Dx(), scaled.Rect.Dy()
	cw, ch := pw/bw, ph/bh
	if dither == ditherNone {
		cw, ch = pw, ph
	}
	if cw < 2 || ch < 2 {
		return nil, errTooSmall
	}

	cv := &ansiCanvas{w: cw, h: ch, matte: matte, dither: dither, noBG: noBG}
	cv.cells = make([][]rgb, ch)
	for y := 0; y < ch; y++ {
		row := make([]rgb, cw)
		for x := 0; x < cw; x++ {
			if dither == ditherNone {
				row[x] = blend(scaled.NRGBAAt(x, y), matte)
			} else {
				row[x] = blockAverage(scaled, x*bw, y*bh, bw, bh, matte)
			}
		}
		cv.cells[y] = row
	}
	return cv, nil
}

// blockAverage averages a bw x bh block of pixels (after compositing each
// of them over the matte) rounding to the nearest integer.
func blockAverage(img *image.NRGBA, x0, y0, bw, bh int, matte rgb) rgb {
