	}
	if c.b > m {
		m = c.b
	}
	return m
}

func pickShade(v uint8, limits []uint8, set []rune) rune {
	i := 0
	for i < len(limits) && v >= limits[i] {
		i++
	}
	return set[i]
}

// renderLines returns the terminal rows, each terminated by a newline.
func (cv *ansiCanvas) renderLines() []string {
	var lines []string
