			}
			writeColor("\x1b[38;2;", row[x])
			sb.WriteRune(pickShade(brightness(row[x]), limits, set))
		}
		sb.WriteString("\x1b[0m\n")
		lines = append(lines, sb.String())
	}
	return lines
}

func itoa(v int) string {
	if v == 0 {
		return "0"
	}
	var buf [8]byte
	i := len(buf)
	for v > 0 {
		i--
		buf[i] = byte('0' + v%10)
		v /= 10
	}
	return string(buf[i:])
}
