				sb.WriteRune('▄')
			}
			sb.WriteString("\x1b[0m\n")
			lines = append(lines, sb.String())
		}
		return lines
	}
	limits, set := shadeBlockLimits, shadeBlocks
	if cv.dither == ditherChars {
		limits, set = shadeCharLimits, shadeChars
	}
	for line := 0; line < cv.h-1; line++ {
		sb.Reset()
		row := cv.cells[line]
