// Minimal decoder for Windows bitmaps: 1/4/8-bit paletted, 24-bit BGR and
// 32-bit BGRA (alpha honoured only with a BITFIELDS header declaring an
// alpha mask). Bottom-up and top-down layouts are both supported.

var errBMPUnsupported = errors.New("bmp: unsupported BMP image")
var errBMPCorrupt = errors.New("bmp: corrupt BMP image")

type bmpHeader struct {
	width, height int
	topDown       bool
	bpp           int
	colors        int
	offset        int
	alpha         bool
}

func readBMPHeader(r io.Reader) (*bmpHeader, error) {
	var fh [14]byte
	if _, err := io.ReadFull(r, fh[:]); err != nil {
		return nil, err
	}
	if fh[0] != 'B' || fh[1] != 'M' {
		return nil, errBMPUnsupported
	}
	offset := int(binary.LittleEndian.Uint32(fh[10:14]))
	var sz [4]byte
	if _, err := io.ReadFull(r, sz[:]); err != nil {
		return nil, err
	}
	infoLen := int(binary.LittleEndian.Uint32(sz[:]))
	if infoLen != 40 && infoLen != 52 && infoLen != 56 && infoLen != 108 && infoLen != 124 {
		return nil, errBMPUnsupported
	}
	info := make([]byte, infoLen-4)
	if _, err := io.ReadFull(r, info); err != nil {
		return nil, err
	}
	width := int(int32(binary.LittleEndian.Uint32(info[0:4])))
	height := int(int32(binary.LittleEndian.Uint32(info[4:8])))
