//go:build ignore

package main

import (
	"encoding/binary"
	"image"
	_ "image/png"
	"os"
	"strconv"
)

// convert PNG (NRGBA) to BMP with given bpp (24, 32, 8 gray palette, 1, 4) and orientation
func main() {
	f, _ := os.Open(os.Args[1])
	img, _, err := image.Decode(f)
	if err != nil {
		panic(err)
	}
	bpp, _ := strconv.Atoi(os.Args[2])
	topdown := len(os.Args) > 4 && os.Args[4] == "td"
	b := img.Bounds()
	w, h := b.Dx(), b.Dy()
	rowBytes := ((w*bpp + 31) / 32) * 4
	var palette []byte
	ncolors := 0
	if bpp <= 8 {
		ncolors = 1 << uint(bpp)
		palette = make([]byte, ncolors*4)
		for i := 0; i < ncolors; i++ {
			v := byte(i * 255 / (ncolors - 1))
			palette[i*4] = v
			palette[i*4+1] = v
			palette[i*4+2] = v
		}
	}
	infoLen := 40
	if bpp == 32 {
		infoLen = 108
	}
	offset := 14 + infoLen + len(palette)
	size := offset + rowBytes*h
	out := make([]byte, size)
	out[0], out[1] = 'B', 'M'
	binary.LittleEndian.PutUint32(out[2:], uint32(size))
	binary.LittleEndian.PutUint32(out[10:], uint32(offset))
	binary.LittleEndian.PutUint32(out[14:], uint32(infoLen))
	binary.LittleEndian.PutUint32(out[18:], uint32(w))
	hh := int32(h)
	if topdown {
		hh = -hh
	}
	binary.LittleEndian.PutUint32(out[22:], uint32(hh))
	binary.LittleEndian.PutUint16(out[26:], 1)
	binary.LittleEndian.PutUint16(out[28:], uint16(bpp))
	if bpp == 32 {
		binary.LittleEndian.PutUint32(out[30:], 3)
		binary.LittleEndian.PutUint32(out[54:], 0xff0000)
		binary.LittleEndian.PutUint32(out[58:], 0xff00)
		binary.LittleEndian.PutUint32(out[62:], 0xff)
		binary.LittleEndian.PutUint32(out[66:], 0xff000000)
	}
	binary.LittleEndian.PutUint32(out[34:], uint32(rowBytes*h))
	binary.LittleEndian.PutUint32(out[46:], uint32(ncolors))
	copy(out[14+infoLen:], palette)
	for y := 0; y < h; y++ {
		ry := h - 1 - y
		if topdown {
			ry = y
		}
		row := out[offset+ry*rowBytes:]
		for x := 0; x < w; x++ {
			r, g, bl, a := img.At(b.Min.X+x, b.Min.Y+y).RGBA()
			// un-premultiply
			var R, G, B, A byte
			if a == 0 {
				R, G, B, A = 0, 0, 0, 0
			} else {
				R = byte(r * 0xffff / a >> 8)
				G = byte(g * 0xffff / a >> 8)
				B = byte(bl * 0xffff / a >> 8)
				A = byte(a >> 8)
			}
			switch bpp {
			case 24:
				row[x*3] = B
				row[x*3+1] = G
				row[x*3+2] = R
			case 32:
				row[x*4] = B
				row[x*4+1] = G
				row[x*4+2] = R
				row[x*4+3] = A
			case 8:
				row[x] = R // gray index
			case 4:
				v := R >> 4
				if x%2 == 0 {
					row[x/2] |= v << 4
				} else {
					row[x/2] |= v
				}
			case 1:
				if R >= 128 {
					row[x/8] |= 1 << uint(7-x%8)
				}
			}
		}
	}
	os.WriteFile(os.Args[3], out, 0644)
}
