// LZW decoder for the TIFF flavour: MSB-first code packing with the code
// width growing one code earlier than in the GIF variant.

var errLZWCorrupt = errors.New("tiff: corrupt LZW data")

type lzwReader struct {
	src      []byte
	pos      int
	bits     uint32
	nbits    uint
	width    uint
	prefix   [4096]uint16
	suffix   [4096]byte
	first    [4096]byte
	length   [4096]int
	next     int
	last     int
	out      []byte
	outPos   int
	done     bool
	tmp      [4096]byte
}

const (
	lzwClear = 256
	lzwEOI   = 257
)

func newTIFFLZWReader(data []byte) *lzwReader {
	r := &lzwReader{src: data}
	r.reset()
	return r
}

func (r *lzwReader) reset() {
	r.width = 9
	r.next = 258
	r.last = -1
	for i := 0; i < 256; i++ {
		r.prefix[i] = 0xffff
		r.suffix[i] = byte(i)
		r.first[i] = byte(i)
		r.length[i] = 1
	}
}

func (r *lzwReader) readCode() (int, bool) {
	for r.nbits < r.width {
		if r.pos >= len(r.src) {
			return 0, false
		}
		r.bits |= uint32(r.src[r.pos]) << (24 - r.nbits)
		r.pos++
		r.nbits += 8
	}
	code := int(r.bits >> (32 - r.width))
	r.bits <<= r.width
	r.nbits -= r.width
	return code, true
}

// expand writes the string for code into tmp and returns it.
func (r *lzwReader) expand(code int) []byte {
	n := r.length[code]
	buf := r.tmp[:n]
	c := code
	for i := n - 1; i >= 0; i-- {
		buf[i] = r.suffix[c]
		c = int(r.prefix[c])
	}
	return buf
}

func (r *lzwReader) Read(p []byte) (int, error) {
	n := 0
	for n < len(p) {
		if r.outPos < len(r.out) {
			m := copy(p[n:], r.out[r.outPos:])
			r.outPos += m
			n += m
			continue
		}
		if r.done {
			break
		}
		code, ok := r.readCode()
		if !ok {
			r.done = true
			break
		}
		switch {
		case code == lzwClear:
			r.reset()
			continue
		case code == lzwEOI:
			r.done = true
			continue
		case code < r.next || (code == r.next && r.last >= 0):
			var str []byte
			if r.last < 0 {
				if code >= 256 {
					return n, errLZWCorrupt
				}
				str = r.expand(code)
			} else {
				var firstByte byte
				if code < r.next {
					str = r.expand(code)
					firstByte = str[0]
				} else {
					// KwKwK case
					prev := r.expand(r.last)
					firstByte = prev[0]
					str = append(r.tmp[:0:0], prev...)
					str = append(str, firstByte)
				}
				if r.next < 4096 {
					r.prefix[r.next] = uint16(r.last)
					r.suffix[r.next] = firstByte
					r.first[r.next] = r.first[r.last]
					r.length[r.next] = r.length[r.last] + 1
					r.next++
				}
				if code == r.next-1 && code >= 258 && r.length[code] > len(r.tmp) {
					return n, errLZWCorrupt
				}
				if code == r.next-1 && code >= 258 {
					str = r.expand(code)
				}
			}
			r.out = append(r.out[:0], str...)
			r.outPos = 0
			r.last = code
			// early change: widen when the next code would not fit
			switch {
			case r.next+1 >= 4096:
				r.width = 12
			case r.next+1 >= 2048:
				r.width = 12
			case r.next+1 >= 1024:
				r.width = 11
			case r.next+1 >= 512:
				r.width = 10
			}
		default:
			return n, errLZWCorrupt
		}
	}
	if n == 0 && r.done {
		return 0, io.EOF
	}
	return n, nil
}
