package main

import (
	"errors"
)

// LZW decoder for the TIFF flavour: MSB-first code packing with the code
// width growing one code earlier than in the GIF variant ("early change").

var errLZWCorrupt = errors.New("tiff: corrupt LZW data")

const (
	lzwClear = 256
	lzwEOI   = 257
)

type lzwState struct {
	prefix [4096]int32
	suffix [4096]byte
	length [4096]int32
	next   int
	width  uint
}

func (s *lzwState) reset() {
	for i := 0; i < 256; i++ {
		s.prefix[i] = -1
		s.suffix[i] = byte(i)
		s.length[i] = 1
	}
	s.next = 258
	s.width = 9
}

func (s *lzwState) add(prev int, c byte) {
	if s.next >= 4096 {
		return
	}
	s.prefix[s.next] = int32(prev)
	s.suffix[s.next] = c
	s.length[s.next] = s.length[prev] + 1
	s.next++
	if s.next+1 >= 1<<s.width && s.width < 12 {
		s.width++
	}
}

// write appends the string of code to out and returns its first byte.
func (s *lzwState) write(out []byte, code int) ([]byte, byte) {
	n := int(s.length[code])
	start := len(out)
	out = append(out, make([]byte, n)...)
	c := code
	for i := n - 1; i >= 0; i-- {
		out[start+i] = s.suffix[c]
		c = int(s.prefix[c])
	}
	return out, out[start]
}

func firstByte(s *lzwState, code int) byte {
	for s.prefix[code] >= 0 {
		code = int(s.prefix[code])
	}
	return s.suffix[code]
}

func lzwDecodeTIFF(src []byte, sizeHint int) ([]byte, error) {
	s := &lzwState{}
	s.reset()
	out := make([]byte, 0, sizeHint)
	var bits uint32
	var nbits uint
	pos := 0
	readCode := func() (int, bool) {
		for nbits < s.width {
			if pos >= len(src) {
				return 0, false
			}
			bits |= uint32(src[pos]) << (24 - nbits)
			pos++
			nbits += 8
		}
		code := int(bits >> (32 - s.width))
		bits <<= s.width
		nbits -= s.width
		return code, true
	}
	old := -1
	for {
		code, ok := readCode()
		if !ok || code == lzwEOI {
			break
		}
		if code == lzwClear {
			s.reset()
			old = -1
			continue
		}
		if old < 0 {
			if code >= 256 {
				return out, errLZWCorrupt
			}
			out, _ = s.write(out, code)
			old = code
			continue
		}
		if code < s.next {
			var fb byte
			out, fb = s.write(out, code)
			s.add(old, fb)
		} else if code == s.next {
			fb := firstByte(s, old)
			s.add(old, fb)
			out, _ = s.write(out, code)
		} else {
			return out, errLZWCorrupt
		}
		old = code
	}
	return out, nil
}
