cat > src/tiff.go <<'EOF'
package main

import (
	"bytes"
	"compress/zlib"
	"encoding/binary"
	"errors"
	"image"
	"image/color"
	"io"
)

// Baseline TIFF decoder: strips or tiles; no compression, LZW, Deflate and
// PackBits; grayscale (1-16 bits), palette and RGB(A) images; horizontal
// differencing predictor.

var errTIFFUnsupported = errors.New("tiff: unsupported feature")
var errTIFFCorrupt = errors.New("tiff: invalid format")

const (
	tagImageWidth     = 256
	tagImageLength    = 257
	tagBitsPerSample  = 258
	tagCompression    = 259
	tagPhotometric    = 262
	tagFillOrder      = 266
	tagStripOffsets   = 273
	tagSamplesPerPix  = 277
	tagRowsPerStrip   = 278
	tagStripByteCount = 279
	tagPlanarConfig   = 284
	tagPredictor      = 317
	tagColorMap       = 320
	tagTileWidth      = 322
	tagTileLength     = 323
	tagTileOffsets    = 324
	tagTileByteCounts = 325
	tagExtraSamples   = 338
	tagSampleFormat   = 339
)

const (
	compNone     = 1
	compLZW      = 5
	compDeflate  = 8
	compDeflate2 = 32946
	compPackBits = 32773
)

const (
	photoWhiteIsZero = 0
	photoBlackIsZero = 1
	photoRGB         = 2
	photoPaletted    = 3
)

type tiffMode int

const (
	modeBilevel tiffMode = iota
	modeGray
	modeGrayInv
	modePaletted
	modeRGB
	modeRGBA
	modeNRGBA
)

type tiffDecoder struct {
	data     []byte
	bo       binary.ByteOrder
	tags     map[int][]uint
	w, h     int
	bpp      int
	spp      int
	mode     tiffMode
	comp     uint
	palette  color.Palette
	predict  bool
	tiled    bool
}

func (d *tiffDecoder) firstVal(tag int) (uint, bool) {
	v, ok := d.tags[tag]
	if !ok || len(v) == 0 {
		return 0, false
	}
	return v[0], true
}

func tiffTypeSize(t uint16) int {
	switch t {
	case 1, 2, 6, 7:
		return 1
	case 3, 8:
		return 2
	case 4, 9, 11:
		return 4
	case 5, 10, 12:
		return 8
	}
	return 0
}

func (d *tiffDecoder) parseIFD(off int) error {
	if off < 0 || off+2 > len(d.data) {
		return errTIFFCorrupt
	}
	n := int(d.bo.Uint16(d.data[off:]))
	off += 2
	if off+n*12 > len(d.data) {
		return errTIFFCorrupt
	}
	d.tags = map[int][]uint{}
	for i := 0; i < n; i++ {
		e := d.data[off+i*12 : off+i*12+12]
		tag := int(d.bo.Uint16(e[0:2]))
		typ := d.bo.Uint16(e[2:4])
		count := int(d.bo.Uint32(e[4:8]))
		size := tiffTypeSize(typ)
		if size == 0 {
			continue
		}
		total := size * count
		var raw []byte
		if total <= 4 {
			raw = e[8 : 8+total]
		} else {
			vo := int(d.bo.Uint32(e[8:12]))
			if vo < 0 || vo+total > len(d.data) || vo+total < vo {
				return errTIFFCorrupt
			}
			raw = d.data[vo : vo+total]
		}
		switch tag {
		case tagImageWidth, tagImageLength, tagBitsPerSample, tagCompression, tagPhotometric,
			tagFillOrder, tagStripOffsets, tagSamplesPerPix, tagRowsPerStrip, tagStripByteCount,
			tagPlanarConfig, tagPredictor, tagColorMap, tagTileWidth, tagTileLength,
			tagTileOffsets, tagTileByteCounts, tagExtraSamples, tagSampleFormat:
			vals := make([]uint, count)
			for j := 0; j < count; j++ {
				switch typ {
				case 1, 2, 6, 7:
					vals[j] = uint(raw[j])
				case 3, 8:
					vals[j] = uint(d.bo.Uint16(raw[j*2:]))
				case 4, 9:
					vals[j] = uint(d.bo.Uint32(raw[j*4:]))
				default:
					return errTIFFUnsupported
				}
			}
			d.tags[tag] = vals
		}
	}
	return nil
}

func decodeTIFF(r io.Reader) (image.Image, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	d := &tiffDecoder{data: data}
	if len(data) < 8 {
		return nil, errTIFFCorrupt
	}
	switch string(data[0:4]) {
	case "II*\x00":
		d.bo = binary.LittleEndian
	case "MM\x00*":
		d.bo = binary.BigEndian
	default:
		return nil, errTIFFCorrupt
	}
	if err := d.parseIFD(int(d.bo.Uint32(data[4:8]))); err != nil {
		return nil, err
	}
	if err := d.setup(); err != nil {
		return nil, err
	}
	return d.decodeImage()
}

func (d *tiffDecoder) setup() error {
	w, ok1 := d.firstVal(tagImageWidth)
	h, ok2 := d.firstVal(tagImageLength)
	if !ok1 || !ok2 || w == 0 || h == 0 || w > 1<<20 || h > 1<<20 {
		return errTIFFCorrupt
	}
	d.w, d.h = int(w), int(h)
	d.comp, _ = d.firstVal(tagCompression)
	if _, ok := d.tags[tagCompression]; !ok {
		d.comp = compNone
	}
	switch d.comp {
	case compNone, compLZW, compDeflate, compDeflate2, compPackBits:
	default:
		return errTIFFUnsupported
	}
	if fo, ok := d.firstVal(tagFillOrder); ok && fo != 1 {
		return errTIFFUnsupported
	}
	if pc, ok := d.firstVal(tagPlanarConfig); ok && pc != 1 {
		return errTIFFUnsupported
	}
	if sf, ok := d.tags[tagSampleFormat]; ok {
		for _, v := range sf {
			if v != 1 {
				return errTIFFUnsupported
			}
		}
	}
	if p, ok := d.firstVal(tagPredictor); ok && p == 2 {
		d.predict = true
	} else if ok && p != 1 {
		return errTIFFUnsupported
	}
	bps := d.tags[tagBitsPerSample]
	if len(bps) == 0 {
		bps = []uint{1}
	}
	d.bpp = int(bps[0])
	for _, b := range bps {
		if int(b) != d.bpp {
			return errTIFFUnsupported
		}
	}
	d.spp = 1
	if v, ok := d.firstVal(tagSamplesPerPix); ok {
		d.spp = int(v)
	}
	photo, _ := d.firstVal(tagPhotometric)
	switch photo {
	case photoRGB:
		if d.bpp != 8 && d.bpp != 16 {
			return errTIFFUnsupported
		}
		switch d.spp {
		case 3:
			d.mode = modeRGB
		case 4:
			es, ok := d.firstVal(tagExtraSamples)
			if !ok {
				return errTIFFUnsupported
			}
			switch es {
			case 1:
				d.mode = modeRGBA
			case 2:
				d.mode = modeNRGBA
			default:
				return errTIFFUnsupported
			}
		default:
			return errTIFFUnsupported
		}
	case photoPaletted:
		if d.spp != 1 || d.bpp > 8 {
			return errTIFFUnsupported
		}
		d.mode = modePaletted
		cm := d.tags[tagColorMap]
		n := 1 << uint(d.bpp)
		if len(cm) < 3*n {
			return errTIFFCorrupt
		}
		d.palette = make(color.Palette, n)
		for i := 0; i < n; i++ {
			d.palette[i] = color.RGBA64{uint16(cm[i]), uint16(cm[n+i]), uint16(cm[2*n+i]), 0xffff}
		}
	case photoWhiteIsZero, photoBlackIsZero:
		if d.spp != 1 {
			return errTIFFUnsupported
		}
		switch d.bpp {
		case 1, 2, 4, 8, 16:
		default:
			return errTIFFUnsupported
		}
		if d.bpp == 1 {
			d.mode = modeBilevel
		} else {
			d.mode = modeGray
		}
		if photo == photoWhiteIsZero {
			d.mode = modeGrayInv
			if d.bpp == 1 {
				d.mode = modeBilevel
			}
		}
	default:
		return errTIFFUnsupported
	}
	if _, ok := d.tags[tagTileWidth]; ok {
		d.tiled = true
	}
	return nil
}

// decompress returns the raw bytes of a strip or tile.
func (d *tiffDecoder) decompress(off, n int, expected int) ([]byte, error) {
	if off < 0 || n < 0 || off+n > len(d.data) {
		return nil, errTIFFCorrupt
	}
	src := d.data[off : off+n]
	switch d.comp {
	case compNone:
		return src, nil
	case compLZW:
		return lzwDecodeTIFF(src, expected)
	case compDeflate, compDeflate2:
		zr, err := zlib.NewReader(bytes.NewReader(src))
		if err != nil {
			return nil, err
		}
		defer zr.Close()
		out, err := io.ReadAll(zr)
		if err != nil && err != io.ErrUnexpectedEOF {
			return nil, err
		}
		return out, nil
	case compPackBits:
		return unpackBits(src), nil
	}
	return nil, errTIFFUnsupported
}

func unpackBits(src []byte) []byte {
	var out []byte
	for i := 0; i < len(src); {
		n := int(int8(src[i]))
		i++
		switch {
		case n >= 0:
			cnt := n + 1
			if i+cnt > len(src) {
				cnt = len(src) - i
			}
			out = append(out, src[i:i+cnt]...)
			i += cnt
		case n == -128:
		default:
			if i < len(src) {
				b := src[i]
				i++
				for k := 0; k < 1-n; k++ {
					out = append(out, b)
				}
			}
		}
	}
	return out
}

func (d *tiffDecoder) newImage() image.Image {
	r := image.Rect(0, 0, d.w, d.h)
	switch d.mode {
	case modeBilevel, modeGray, modeGrayInv:
		if d.bpp == 16 {
			return image.NewGray16(r)
		}
		return image.NewGray(r)
	case modePaletted:
		return image.NewPaletted(r, d.palette)
	case modeRGB, modeRGBA:
		if d.bpp == 16 {
			return image.NewRGBA64(r)
		}
		return image.NewRGBA(r)
	default:
		if d.bpp == 16 {
			return image.NewNRGBA64(r)
		}
		return image.NewNRGBA(r)
	}
}

func (d *tiffDecoder) decodeImage() (image.Image, error) {
	img := d.newImage()
	var blockW, blockH int
	var offsets, counts []uint
	if d.tiled {
		tw, _ := d.firstVal(tagTileWidth)
		th, _ := d.firstVal(tagTileLength)
		blockW, blockH = int(tw), int(th)
		offsets = d.tags[tagTileOffsets]
		counts = d.tags[tagTileByteCounts]
	} else {
		rps, ok := d.firstVal(tagRowsPerStrip)
		if !ok || rps == 0 || int(rps) > d.h {
			rps = uint(d.h)
		}
		blockW, blockH = d.w, int(rps)
		offsets = d.tags[tagStripOffsets]
		counts = d.tags[tagStripByteCount]
	}
	if blockW <= 0 || blockH <= 0 {
		return nil, errTIFFCorrupt
	}
	blocksAcross := (d.w + blockW - 1) / blockW
	blocksDown := (d.h + blockH - 1) / blockH
	nBlocks := blocksAcross * blocksDown
	if len(offsets) < nBlocks {
		return nil, errTIFFCorrupt
	}
	if len(counts) < nBlocks {
		if d.comp != compNone {
			return nil, errTIFFCorrupt
		}
		// derive the byte counts for uncompressed data
		counts = make([]uint, nBlocks)
		rowBytes := (blockW*d.bpp*d.spp + 7) / 8
		for i := range counts {
			counts[i] = uint(rowBytes * blockH)
		}
	}
	rowBytes := (blockW*d.bpp*d.spp + 7) / 8
	for by := 0; by < blocksDown; by++ {
		for bx := 0; bx < blocksAcross; bx++ {
			i := by*blocksAcross + bx
			buf, err := d.decompress(int(offsets[i]), int(counts[i]), rowBytes*blockH)
			if err != nil {
				return nil, err
			}
			x0, y0 := bx*blockW, by*blockH
			x1, y1 := x0+blockW, y0+blockH
			if x1 > d.w {
				x1 = d.w
			}
			if y1 > d.h {
				y1 = d.h
			}
			if err := d.paintBlock(img, buf, x0, y0, x1, y1, blockW); err != nil {
				return nil, err
			}
		}
	}
	return img, nil
}

// paintBlock decodes one strip/tile into img.
func (d *tiffDecoder) paintBlock(img image.Image, buf []byte, x0, y0, x1, y1, blockW int) error {
	rowBytes := (blockW*d.bpp*d.spp + 7) / 8
	rows := y1 - y0
	if len(buf) < rowBytes*rows {
		return errTIFFCorrupt
	}
	if d.predict {
		if d.bpp == 8 {
			for y := 0; y < rows; y++ {
				row := buf[y*rowBytes : (y+1)*rowBytes]
				for i := d.spp; i < len(row); i++ {
					row[i] += row[i-d.spp]
				}
			}
		} else if d.bpp == 16 {
			step := d.spp * 2
			for y := 0; y < rows; y++ {
				row := buf[y*rowBytes : (y+1)*rowBytes]
				for i := step; i+1 < len(row); i += 2 {
					v := d.bo.Uint16(row[i:]) + d.bo.Uint16(row[i-step:])
					d.bo.PutUint16(row[i:], v)
				}
			}
		} else {
			return errTIFFUnsupported
		}
	}
	width := x1 - x0
	switch m := img.(type) {
	case *image.Gray:
		for y := 0; y < rows; y++ {
			row := buf[y*rowBytes:]
			dst := m.Pix[(y0+y)*m.Stride+x0 : (y0+y)*m.Stride+x0+width]
			switch d.bpp {
			case 8:
				copy(dst, row[:width])
			case 1, 2, 4:
				per := 8 / d.bpp
				mask := byte(1<<uint(d.bpp) - 1)
				scale := byte(255 / int(mask))
				for x := 0; x < width; x++ {
					shift := uint(8 - d.bpp*(x%per+1))
					v := (row[x/per] >> shift) & mask
					dst[x] = v * scale
				}
			}
			if d.mode == modeGrayInv || (d.mode == modeBilevel && d.isWhiteZero()) {
				for x := range dst {
					dst[x] = 0xff - dst[x]
				}
			}
		}
	case *image.Gray16:
		for y := 0; y < rows; y++ {
			row := buf[y*rowBytes:]
			dst := m.Pix[(y0+y)*m.Stride+x0*2:]
			for x := 0; x < width; x++ {
				v := d.bo.Uint16(row[x*2:])
				if d.mode == modeGrayInv {
					v = 0xffff - v
				}
				dst[x*2] = byte(v >> 8)
				dst[x*2+1] = byte(v)
			}
		}
	case *image.Paletted:
		for y := 0; y < rows; y++ {
			row := buf[y*rowBytes:]
			dst := m.Pix[(y0+y)*m.Stride+x0 : (y0+y)*m.Stride+x0+width]
			switch d.bpp {
			case 8:
				copy(dst, row[:width])
			default:
				per := 8 / d.bpp
				mask := byte(1<<uint(d.bpp) - 1)
				for x := 0; x < width; x++ {
					shift := uint(8 - d.bpp*(x%per+1))
					dst[x] = (row[x/per] >> shift) & mask
				}
			}
		}
	case *image.RGBA:
		for y := 0; y < rows; y++ {
			row := buf[y*rowBytes:]
			dst := m.Pix[(y0+y)*m.Stride+x0*4:]
			for x := 0; x < width; x++ {
				s := row[x*d.spp:]
				dst[x*4+0] = s[0]
				dst[x*4+1] = s[1]
				dst[x*4+2] = s[2]
				if d.spp == 4 {
					dst[x*4+3] = s[3]
				} else {
					dst[x*4+3] = 0xff
				}
			}
		}
	case *image.NRGBA:
		for y := 0; y < rows; y++ {
			row := buf[y*rowBytes:]
			dst := m.Pix[(y0+y)*m.Stride+x0*4:]
			for x := 0; x < width; x++ {
				copy(dst[x*4:x*4+4], row[x*4:x*4+4])
			}
		}
	case *image.RGBA64:
		for y := 0; y < rows; y++ {
			row := buf[y*rowBytes:]
			dst := m.Pix[(y0+y)*m.Stride+x0*8:]
			for x := 0; x < width; x++ {
				s := row[x*d.spp*2:]
				for c := 0; c < 3; c++ {
					v := d.bo.Uint16(s[c*2:])
					dst[x*8+c*2] = byte(v >> 8)
					dst[x*8+c*2+1] = byte(v)
				}
				if d.spp == 4 {
					v := d.bo.Uint16(s[6:])
					dst[x*8+6] = byte(v >> 8)
					dst[x*8+7] = byte(v)
				} else {
					dst[x*8+6], dst[x*8+7] = 0xff, 0xff
				}
			}
		}
	case *image.NRGBA64:
		for y := 0; y < rows; y++ {
			row := buf[y*rowBytes:]
			dst := m.Pix[(y0+y)*m.Stride+x0*8:]
			for x := 0; x < width; x++ {
				s := row[x*8:]
				for c := 0; c < 4; c++ {
					v := d.bo.Uint16(s[c*2:])
					dst[x*8+c*2] = byte(v >> 8)
					dst[x*8+c*2+1] = byte(v)
				}
			}
		}
	}
	return nil
}

func (d *tiffDecoder) isWhiteZero() bool {
	p, _ := d.firstVal(tagPhotometric)
	return p == photoWhiteIsZero
}

func decodeTIFFConfig(r io.Reader) (image.Config, error) {
	img, err := decodeTIFF(r)
	if err != nil {
		return image.Config{}, err
	}
	return image.Config{ColorModel: img.ColorModel(), Width: img.Bounds().Dx(), Height: img.Bounds().Dy()}, nil
}

func init() {
	image.RegisterFormat("tiff", "II\x2A\x00", decodeTIFF, decodeTIFFConfig)
	image.RegisterFormat("tiff", "MM\x00\x2A", decodeTIFF, decodeTIFFConfig)
}
