// usage: totiff in.png out.tif mode comp [opts]
// mode: rgb, rgba(assoc), nrgba, gray8, gray16, gray4, gray1, white1, pal8, pal4, rgb16
// comp: none, lzw, deflate, packbits
// opts: be (big endian), pred (predictor), tile (tiles 16x16), rps=N

type entry struct {
	tag   uint16
	typ   uint16
	vals  []uint32
	bytes []byte
}

func main() {
	f, _ := os.Open(os.Args[1])
	img, _, err := image.Decode(f)
	if err != nil {
		panic(err)
	}
	out := os.Args[2]
	mode := os.Args[3]
	comp := os.Args[4]
	opts := strings.Join(os.Args[5:], " ")
	be := strings.Contains(opts, "be")
	pred := strings.Contains(opts, "pred")
	tile := strings.Contains(opts, "tile")
	rps := 0
	for _, o := range os.Args[5:] {
		if strings.HasPrefix(o, "rps=") {
			rps, _ = strconv.Atoi(o[4:])
		}
	}
	var bo binary.ByteOrder = binary.LittleEndian
	if be {
		bo = binary.BigEndian
	}
	b := img.Bounds()
	w, h := b.Dx(), b.Dy()
	var bps, spp int
	var photo uint32
	var extra []uint32
	var colormap []uint32
	switch mode {
	case "rgb":
		bps, spp, photo = 8, 3, 2
	case "rgb16":
		bps, spp, photo = 16, 3, 2
	case "rgba":
		bps, spp, photo = 8, 4, 2
		extra = []uint32{1}
	case "rgba16":
		bps, spp, photo = 16, 4, 2
		extra = []uint32{1}
	case "nrgba":
		bps, spp, photo = 8, 4, 2
		extra = []uint32{2}
	case "nrgba16":
		bps, spp, photo = 16, 4, 2
		extra = []uint32{2}
	case "gray8":
		bps, spp, photo = 8, 1, 1
	case "gray16":
		bps, spp, photo = 16, 1, 1
	case "gray4":
		bps, spp, photo = 4, 1, 1
	case "gray2":
		bps, spp, photo = 2, 1, 1
	case "gray1":
		bps, spp, photo = 1, 1, 1
	case "white1":
		bps, spp, photo = 1, 1, 0
	case "white8":
		bps, spp, photo = 8, 1, 0
	case "pal8":
		bps, spp, photo = 8, 1, 3
		colormap = make([]uint32, 3*256)
		for i := 0; i < 256; i++ {
			colormap[i] = uint32(i * 257)
			colormap[256+i] = uint32((255 - i) * 257)
			colormap[512+i] = uint32((i * 7 % 256) * 257)
		}
	case "pal4":
		bps, spp, photo = 4, 1, 3
		colormap = make([]uint32, 3*16)
		for i := 0; i < 16; i++ {
			colormap[i] = uint32(i * 17 * 257)
			colormap[16+i] = uint32((15 - i) * 17 * 257)
			colormap[32+i] = uint32((i * 50 % 256) * 257)
		}
	}
	// sample getter
	pixelBytes := func(x, y int) []byte {
		c := img.At(b.Min.X+x, b.Min.Y+y)
		r, g, bl, a := c.RGBA()
		var R, G, B, A uint32
		if a == 0 {
			R, G, B, A = 0, 0, 0, 0
		} else {
			R, G, B, A = r*0xffff/a, g*0xffff/a, bl*0xffff/a, a
		}
		buf := make([]byte, 0, 8)
		put16 := func(v uint32) {
			var t [2]byte
			bo.PutUint16(t[:], uint16(v))
			buf = append(buf, t[:]...)
		}
		switch mode {
		case "rgb":
			buf = append(buf, byte(R>>8), byte(G>>8), byte(B>>8))
		case "rgb16":
			put16(R)
			put16(G)
			put16(B)
		case "rgba":
			buf = append(buf, byte(r>>8), byte(g>>8), byte(bl>>8), byte(a>>8))
		case "rgba16":
			put16(r)
			put16(g)
			put16(bl)
			put16(a)
		case "nrgba":
			buf = append(buf, byte(R>>8), byte(G>>8), byte(B>>8), byte(A>>8))
		case "nrgba16":
			put16(R)
			put16(G)
			put16(B)
			put16(A)
		case "gray8", "pal8":
			buf = append(buf, byte(R>>8))
		case "white8":
			buf = append(buf, 255-byte(R>>8))
		case "gray16":
			put16(R)
		}
		return buf
	}
	// pack a block of rows [y0,y1) x [x0,x1) with block width bw into bytes
	packBlock := func(x0, y0, bw, bh int) []byte {
		rowBytes := (bw*bps*spp + 7) / 8
		data := make([]byte, rowBytes*bh)
		for yy := 0; yy < bh; yy++ {
			y := y0 + yy
			if y >= h {
				break
			}
			row := data[yy*rowBytes : (yy+1)*rowBytes]
			for xx := 0; xx < bw; xx++ {
				x := x0 + xx
				if x >= w {
					break
				}
				if bps >= 8 {
					pb := pixelBytes(x, y)
					copy(row[xx*len(pb):], pb)
				} else {
					c := img.At(b.Min.X+x, b.Min.Y+y)
					r, _, _, _ := c.RGBA()
					v := byte(r >> 8)
					var idx byte
					switch bps {
					case 4:
						idx = v >> 4
					case 2:
						idx = v >> 6
					case 1:
						if v >= 128 {
							idx = 1
						}
						if mode == "white1" {
							idx ^= 1
						}
					}
					per := 8 / bps
					shift := uint(8 - bps*(xx%per+1))
					row[xx/per] |= idx << shift
				}
			}
			if pred {
				if bps == 8 {
					for i := len(row) - 1; i >= spp; i-- {
						row[i] -= row[i-spp]
					}
				} else if bps == 16 {
					step := spp * 2
					for i := len(row) - 2; i >= step; i -= 2 {
						v := bo.Uint16(row[i:]) - bo.Uint16(row[i-step:])
						bo.PutUint16(row[i:], v)
					}
				}
			}
		}
		return data
	}
	compress := func(data []byte) []byte {
		switch comp {
		case "none":
			return data
		case "lzw":
			return lzwEncode(data)
		case "deflate":
			var buf bytes.Buffer
			zw := zlib.NewWriter(&buf)
			zw.Write(data)
			zw.Close()
			return buf.Bytes()
		case "packbits":
			return packBits(data)
		}
		panic("bad comp")
	}
	compCode := map[string]uint32{"none": 1, "lzw": 5, "deflate": 8, "packbits": 32773}[comp]

	var blocks [][]byte
	var entries []entry
	add := func(tag, typ uint16, vals ...uint32) {
		entries = append(entries, entry{tag: tag, typ: typ, vals: vals})
	}
	add(256, 4, uint32(w))
	add(257, 4, uint32(h))
	bpsv := make([]uint32, spp)
	for i := range bpsv {
		bpsv[i] = uint32(bps)
	}
	add(258, 3, bpsv...)
	add(259, 3, compCode)
	add(262, 3, photo)
	add(277, 3, uint32(spp))
	if pred {
		add(317, 3, 2)
	}
	if colormap != nil {
		add(320, 3, colormap...)
	}
	if extra != nil {
		add(338, 3, extra...)
	}
	if tile {
		tw, th := 16, 16
		add(322, 4, uint32(tw))
		add(323, 4, uint32(th))
		for y0 := 0; y0 < h; y0 += th {
			for x0 := 0; x0 < w; x0 += tw {
				blocks = append(blocks, compress(packBlock(x0, y0, tw, th)))
			}
		}
	} else {
		if rps == 0 {
			rps = h
		}
		add(278, 4, uint32(rps))
		for y0 := 0; y0 < h; y0 += rps {
			bh := rps
			if y0+bh > h {
				bh = h - y0
			}
			blocks = append(blocks, compress(packBlock(0, y0, w, bh)))
		}
	}
	// layout: header(8) + IFD + extra data + blocks
	// compute offsets: entries sorted by tag; add strip/tile offsets & counts placeholders
	offTag, cntTag := uint16(273), uint16(279)
	if tile {
		offTag, cntTag = 324, 325
	}
	offs := make([]uint32, len(blocks))
	cnts := make([]uint32, len(blocks))
	for i := range blocks {
		cnts[i] = uint32(len(blocks[i]))
	}
	entries = append(entries, entry{tag: offTag, typ: 4, vals: offs}, entry{tag: cntTag, typ: 4, vals: cnts})
	// sort entries by tag
	for i := 0; i < len(entries); i++ {
		for j := i + 1; j < len(entries); j++ {
			if entries[j].tag < entries[i].tag {
				entries[i], entries[j] = entries[j], entries[i]
			}
		}
	}
	ifdSize := 2 + 12*len(entries) + 4
	dataOff := 8 + ifdSize
	// compute extra data sizes
	extraSize := 0
	for _, e := range entries {
		sz := len(e.vals) * map[uint16]int{3: 2, 4: 4}[e.typ]
		if sz > 4 {
			extraSize += sz
			if extraSize%2 == 1 {
				extraSize++
			}
		}
	}
	blockOff := dataOff + extraSize
	for i := range blocks {
		offs[i] = uint32(blockOff)
		blockOff += len(blocks[i])
	}
	// update offsets entry
	for i := range entries {
		if entries[i].tag == offTag {
			entries[i].vals = offs
		}
	}
	buf := make([]byte, blockOff)
	if be {
		copy(buf, "MM\x00*")
	} else {
		copy(buf, "II*\x00")
	}
	bo.PutUint32(buf[4:], 8)
	bo.PutUint16(buf[8:], uint16(len(entries)))
	ep := 10
	xp := dataOff
	for _, e := range entries {
		bo.PutUint16(buf[ep:], e.tag)
		bo.PutUint16(buf[ep+2:], e.typ)
		bo.PutUint32(buf[ep+4:], uint32(len(e.vals)))
		tsz := map[uint16]int{3: 2, 4: 4}[e.typ]
		sz := len(e.vals) * tsz
		var dst []byte
		if sz > 4 {
			bo.PutUint32(buf[ep+8:], uint32(xp))
			dst = buf[xp:]
			xp += sz
			if xp%2 == 1 {
				xp++
			}
		} else {
			dst = buf[ep+8:]
		}
		for i, v := range e.vals {
			if tsz == 2 {
				bo.PutUint16(dst[i*2:], uint16(v))
			} else {
				bo.PutUint32(dst[i*4:], v)
			}
		}
		ep += 12
	}
	bo.PutUint32(buf[ep:], 0)
	for i, blk := range blocks {
		copy(buf[offs[i]:], blk)
	}
	os.WriteFile(out, buf, 0644)
}

func packBits(data []byte) []byte {
	var out []byte
	i := 0
	for i < len(data) {
		// find run
		j := i
		for j+1 < len(data) && data[j+1] == data[i] && j-i < 126 {
			j++
		}
		run := j - i + 1
		if run >= 2 {
			out = append(out, byte(-(run - 1)), data[i])
			i += run
			continue
		}
		// literal run
		k := i
		for k < len(data) && k-i < 127 {
			if k+2 < len(data) && data[k] == data[k+1] && data[k+1] == data[k+2] {
				break
			}
			k++
		}
		out = append(out, byte(k-i-1))
		out = append(out, data[i:k]...)
		i = k
	}
	return out
}

// TIFF LZW encoder (MSB first, early change)
func lzwEncode(data []byte) []byte {
	var out []byte
	var bits uint32
	var nbits uint
	width := uint(9)
	emit := func(code int) {
		bits |= uint32(code) << (32 - width - nbits)
		nbits += width
		for nbits >= 8 {
			out = append(out, byte(bits>>24))
			bits <<= 8
			nbits -= 8
		}
	}
	dict := map[string]int{}
	reset := func() {
		dict = map[string]int{}
		for i := 0; i < 256; i++ {
			dict[string([]byte{byte(i)})] = i
		}
		width = 9
	}
	reset()
	emit(256)
	next := 258
	var cur []byte
	for _, c := range data {
		cand := append(append([]byte{}, cur...), c)
		if _, ok := dict[string(cand)]; ok {
			cur = cand
			continue
		}
		emit(dict[string(cur)])
		dict[string(cand)] = next
		next++
		if next+1 >= 1<<width {
			if width < 12 {
				width++
			}
		}
		if next >= 4094 {
			emit(256)
			reset()
			next = 258
		}
		cur = []byte{c}
	}
	if len(cur) > 0 {
		emit(dict[string(cur)])
	}
	emit(257)
	if nbits > 0 {
		out = append(out, byte(bits>>24))
	}
	return out
}
