package main

import (
	"bytes"
	"encoding/binary"
	"errors"
	"image"
	"io"
)

// WebP container parsing. Lossy (VP8) and lossless (VP8L) bitstreams are
// supported, including the extended format with a separate alpha chunk.

var errWebPInvalid = errors.New("webp: invalid format")
var errWebPUnsupported = errors.New("webp: unsupported feature")

func decodeWebP(r io.Reader) (image.Image, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	if len(data) < 12 || string(data[0:4]) != "RIFF" || string(data[8:12]) != "WEBP" {
		return nil, errWebPInvalid
	}
	riffLen := int(binary.LittleEndian.Uint32(data[4:8]))
	if riffLen < 4 {
		return nil, errWebPInvalid
	}
	if riffLen+8 < len(data) {
		data = data[:riffLen+8]
	}
	pos := 12
	var alphaChunk []byte
	haveAlphaChunk := false
	extended := false
	for pos+8 <= len(data) {
		fourcc := string(data[pos : pos+4])
		size := int(binary.LittleEndian.Uint32(data[pos+4 : pos+8]))
		pos += 8
		if size < 0 || pos+size > len(data) {
			return nil, errWebPInvalid
		}
		chunk := data[pos : pos+size]
		pos += size + (size & 1)
		switch fourcc {
		case "VP8X":
			if size < 10 {
				return nil, errWebPInvalid
			}
			extended = true
			flags := chunk[0]
			if flags&0x02 != 0 { // animation
				return nil, errWebPUnsupported
			}
		case "ALPH":
			if extended {
				alphaChunk = chunk
				haveAlphaChunk = true
			}
		case "VP8 ":
			img, err := decodeVP8Frame(chunk)
			if err != nil {
				return nil, err
			}
			if haveAlphaChunk {
				return applyAlphaChunk(img, alphaChunk)
			}
			return img, nil
		case "VP8L":
			return decodeVP8L(chunk)
		default:
			// ICCP, EXIF, XMP, ANIM, ANMF, unknown: skipped
		}
	}
	return nil, errWebPInvalid
}

func decodeWebPConfig(r io.Reader) (image.Config, error) {
	img, err := decodeWebP(r)
	if err != nil {
		return image.Config{}, err
	}
	return image.Config{ColorModel: img.ColorModel(), Width: img.Bounds().Dx(), Height: img.Bounds().Dy()}, nil
}

// applyAlphaChunk combines a decoded lossy frame with an ALPH chunk.
func applyAlphaChunk(ycc *image.YCbCr, chunk []byte) (image.Image, error) {
	if len(chunk) < 1 {
		return nil, errWebPInvalid
	}
	hdr := chunk[0]
	compression := hdr & 0x03
	filter := (hdr >> 2) & 0x03
	// preprocessing bits (4..5) and reserved bits (6..7) are ignored
	w, h := ycc.Rect.Dx(), ycc.Rect.Dy()
	var alpha []byte
	switch compression {
	case 0:
		if len(chunk)-1 < w*h {
			return nil, errWebPInvalid
		}
		alpha = make([]byte, w*h)
		copy(alpha, chunk[1:1+w*h])
	case 1:
		pix, err := decodeVP8LStream(bytes.NewReader(chunk[1:]), w, h)
		if err != nil {
			return nil, err
		}
		alpha = make([]byte, w*h)
		for i := 0; i < w*h; i++ {
			alpha[i] = byte(pix[i] >> 8) // green channel
		}
	default:
		return nil, errWebPUnsupported
	}
	unfilterAlpha(alpha, w, h, filter)
	out := &image.NYCbCrA{
		YCbCr:   *ycc,
		A:       alpha,
		AStride: w,
	}
	return out, nil
}

// unfilterAlpha reverses the spatial prediction applied to the alpha plane.
func unfilterAlpha(a []byte, w, h int, filter byte) {
	if filter == 0 {
		return
	}
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			var pred byte
			switch {
			case x == 0 && y == 0:
				pred = 0
			case y == 0:
				pred = a[x-1]
			case x == 0:
				pred = a[(y-1)*w]
			default:
				left := int(a[y*w+x-1])
				top := int(a[(y-1)*w+x])
				topLeft := int(a[(y-1)*w+x-1])
				switch filter {
				case 1:
					pred = byte(left)
				case 2:
					pred = byte(top)
				default:
					g := left + top - topLeft
					if g < 0 {
						g = 0
					} else if g > 255 {
						g = 255
					}
					pred = byte(g)
				}
			}
			a[y*w+x] += pred
		}
	}
}

func init() {
	image.RegisterFormat("webp", "RIFF????WEBPVP8", decodeWebP, decodeWebPConfig)
}
EOF
echo ok"}

