	0x64, 0x6c, 0x42, 0x4e, 0x76, 0x7a, 0x21, 0x2f, 0x75, 0x7b,
	0x31, 0x3f, 0x63, 0x6d, 0x52, 0x5e, 0x00, 0x74, 0x7c, 0x41,
	0x4f, 0x10, 0x20, 0x62, 0x6e, 0x30, 0x73, 0x7d, 0x51, 0x5f,
	0x40, 0x72, 0x7e, 0x61, 0x6f, 0x50, 0x71, 0x7f, 0x60, 0x70,
}

func planeCodeToDistance(width, code int) int {
	if code > 120 {
		return code - 120
	}
	v := int(distanceMap[code-1])
	xoff := 8 - (v & 0xf)
	yoff := v >> 4
	dist := xoff + yoff*width
	if dist < 1 {
		dist = 1
	}
	return dist
}

// decodeEntropyImage decodes a w x h ARGB image. When isMain is false no
// meta Huffman codes are present.
func (d *vp8lDecoder) decodeEntropyImage(w, h int, isMain bool) ([]uint32, error) {
	br := d.br
	var cacheBits uint
	if br.readBits(1) == 1 {
		cacheBits = uint(br.readBits(4))
		if cacheBits < 1 || cacheBits > 11 {
			return nil, errVP8LInvalid
		}
	}
	var metaImage []uint32
	metaBits := uint(0)
	numGroups := 1
	if isMain && br.readBits(1) == 1 {
		metaBits = uint(br.readBits(3)) + 2
		mw, mh := divRoundUp(w, 1<<metaBits), divRoundUp(h, 1<<metaBits)
		var err error
		metaImage, err = d.decodeEntropyImage(mw, mh, false)
		if err != nil {
			return nil, err
		}
		for i := range metaImage {
			g := int(metaImage[i]>>8) & 0xffff
			metaImage[i] = uint32(g)
			if g+1 > numGroups {
				numGroups = g + 1
			}
		}
	}
	if br.err != nil {
		return nil, br.err
	}
	groups := make([]*huffmanGroup, numGroups)
	for i := range groups {
		g, err := readHuffmanGroup(br, cacheBits)
		if err != nil {
			return nil, err
		}
		groups[i] = g
	}
	var cache []uint32
	if cacheBits > 0 {
		cache = make([]uint32, 1<<cacheBits)
	}
	insert := func(argb uint32) {
		if cache != nil {
			cache[(0x1e35a7bd*argb)>>(32-cacheBits)] = argb
		}
	}
	pix := make([]uint32, w*h)
	n := w * h
	pos := 0
	x, y := 0, 0
	group := groups[0]
	for pos < n {
		if metaImage != nil {
			group = groups[metaImage[(y>>metaBits)*divRoundUp(w, 1<<metaBits)+(x>>metaBits)]]
		}
		s := group.codes[0].read(br)
		if br.err != nil {
			return nil, br.err
		}
		switch {
		case s < numLiteralCodes:
			r := uint32(group.codes[1].read(br))
			b := uint32(group.codes[2].read(br))
			a := uint32(group.codes[3].read(br))
			argb := a<<24 | r<<16 | uint32(s)<<8 | b
			pix[pos] = argb
			insert(argb)
			pos++
			x++
			if x == w {
				x = 0
				y++
			}
		case s < numLiteralCodes+numLengthCodes:
			length := d.getCopyDistance(s - numLiteralCodes)
			ds := group.codes[4].read(br)
			dist := planeCodeToDistance(w, d.getCopyDistance(ds))
			if br.err != nil {
				return nil, br.err
			}
			if pos-dist < 0 || pos+length > n {
				return nil, errVP8LInvalid
			}
			for i := 0; i < length; i++ {
				pix[pos] = pix[pos-dist]
				insert(pix[pos])
				pos++
			}
			x += length
			for x >= w {
				x -= w
				y++
			}
		default:
			idx := s - numLiteralCodes - numLengthCodes
			if cache == nil || idx >= len(cache) {
				return nil, errVP8LInvalid
			}
			argb := cache[idx]
			pix[pos] = argb
			insert(argb)
			pos++
			x++
			if x == w {
				x = 0
				y++
			}
		}
	}
	if br.err != nil {
		return nil, br.err
	}
	return pix, nil
}

// transform descriptors
type vp8lTransform struct {
	kind    int
	bits    uint
	data    []uint32
	xsize   int // original width before the transform (for color indexing)
	palette []uint32
}

const (
	xformPredictor = iota
	xformColor
	xformSubtractGreen
	xformColorIndexing
)

// decodeVP8LStream decodes a stream without the 5-byte header (as used by
// alpha chunks) with known dimensions.
func decodeVP8LStream(r io.ByteReader, w, h int) ([]uint32, error) {
	d := &vp8lDecoder{br: &lsbBitReader{r: r}}
	return d.decodeImageStream(w, h)
}

func (d *vp8lDecoder) decodeImageStream(w, h int) ([]uint32, error) {
	br := d.br
	var transforms []vp8lTransform
	seen := [4]bool{}
	curW := w
	for br.readBits(1) == 1 {
		kind := int(br.readBits(2))
		if seen[kind] {
			return nil, errVP8LInvalid
		}
		seen[kind] = true
		t := vp8lTransform{kind: kind, xsize: curW}
		switch kind {
		case xformPredictor, xformColor:
			t.bits = uint(br.readBits(3)) + 2
			bw, bh := divRoundUp(curW, 1<<t.bits), divRoundUp(h, 1<<t.bits)
			data, err := d.decodeEntropyImage(bw, bh, false)
			if err != nil {
				return nil, err
			}
			t.data = data
		case xformSubtractGreen:
		case xformColorIndexing:
			numColors := int(br.readBits(8)) + 1
			pal, err := d.decodeEntropyImage(numColors, 1, false)
			if err != nil {
				return nil, err
			}
			// palette entries are delta coded per channel
			for i := 1; i < numColors; i++ {
				pal[i] = addARGB(pal[i], pal[i-1])
			}
			full := make([]uint32, 256)
			copy(full, pal)
			t.palette = full
			switch {
			case numColors > 16:
				t.bits = 0
			case numColors > 4:
				t.bits = 1
			case numColors > 2:
				t.bits = 2
			default:
				t.bits = 3
			}
			curW = divRoundUp(curW, 1<<t.bits)
		}
		transforms = append(transforms, t)
		if br.err != nil {
			return nil, br.err
		}
	}
	if br.err != nil {
		return nil, br.err
	}
	pix, err := d.decodeEntropyImage(curW, h, true)
	if err != nil {
		return nil, err
	}
	// apply inverse transforms in reverse order
	for i := len(transforms) - 1; i >= 0; i-- {
		t := &transforms[i]
		switch t.kind {
		case xformColorIndexing:
			pix = inverseColorIndexing(pix, t, h)
			curW = t.xsize
		case xformSubtractGreen:
			for j, p := range pix {
				g := (p >> 8) & 0xff
				r := ((p >> 16) + g) & 0xff
				b := (p + g) & 0xff
				pix[j] = p&0xff00ff00 | r<<16 | b
			}
		case xformColor:
			inverseColorTransform(pix, t, curW, h)
		case xformPredictor:
			inversePredictor(pix, t, curW, h)
		}
	}
	return pix, nil
}

func addARGB(a, b uint32) uint32 {
	return ((a & 0xff00ff00) + (b & 0xff00ff00)) & 0xff00ff00 |
		((a & 0x00ff00ff) + (b & 0x00ff00ff)) & 0x00ff00ff
}

func inverseColorIndexing(pix []uint32, t *vp8lTransform, h int) []uint32 {
	w := t.xsize
	out := make([]uint32, w*h)
	if t.bits == 0 {
		for i := range out {
			out[i] = t.palette[(pix[i]>>8)&0xff]
		}
		return out
	}
	packedW := divRoundUp(w, 1<<t.bits)
	perPixel := 1 << t.bits
	bitsPer := uint(8 >> t.bits)
	mask := uint32(1)<<bitsPer - 1
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			packed := pix[y*packedW+x/perPixel]
			g := (packed >> 8) & 0xff
			shift := uint(x%perPixel) * bitsPer
			idx := (g >> shift) & mask
			out[y*w+x] = t.palette[idx]
		}
	}
	return out
}

func colorTransformDelta(t, c uint8) int32 {
	return (int32(int8(t)) * int32(int8(c))) >> 5
}

func inverseColorTransform(pix []uint32, t *vp8lTransform, w, h int) {
	bw := divRoundUp(w, 1<<t.bits)
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			m := t.data[(y>>t.bits)*bw+(x>>t.bits)]
			g2r := uint8(m)
			g2b := uint8(m >> 8)
			r2b := uint8(m >> 16)
			p := pix[y*w+x]
			r := uint8(p >> 16)
			g := uint8(p >> 8)
			b := uint8(p)
			r = uint8(int32(r) + colorTransformDelta(g2r, g))
			b = uint8(int32(b) + colorTransformDelta(g2b, g))
			b = uint8(int32(b) + colorTransformDelta(r2b, r))
			pix[y*w+x] = p&0xff00ff00 | uint32(r)<<16 | uint32(b)
		}
	}
}

func average2(a, b uint32) uint32 {
	return (((a ^ b) & 0xfefefefe) >> 1) + (a & b)
}

func absDiff(a, b uint32) int32 {
	d := int32(a) - int32(b)
	if d < 0 {
		return -d
	}
	return d
}

func selectPredictor(l, t, tl uint32) uint32 {
	// pL = sum over channels |T - TL|, pT = sum |L - TL|
	var pl, pt int32
	for shift := uint(0); shift < 32; shift += 8 {
		pl += absDiff((t>>shift)&0xff, (tl>>shift)&0xff)
		pt += absDiff((l>>shift)&0xff, (tl>>shift)&0xff)
	}
	if pl < pt {
		return l
	}
	return t
}

func clamp255(v int32) uint32 {
	if v < 0 {
		return 0
	}
	if v > 255 {
		return 255
	}
	return uint32(v)
}

func clampAddSubtractFull(a, b, c uint32) uint32 {
	var out uint32
	for shift := uint(0); shift < 32; shift += 8 {
		v := int32((a>>shift)&0xff) + int32((b>>shift)&0xff) - int32((c>>shift)&0xff)
		out |= clamp255(v) << shift
	}
	return out
}

func clampAddSubtractHalf(a, b uint32) uint32 {
	var out uint32
	for shift := uint(0); shift < 32; shift += 8 {
		av := int32((a >> shift) & 0xff)
		bv := int32((b >> shift) & 0xff)
		v := av + (av-bv)/2
		out |= clamp255(v) << shift
	}
	return out
}

func predict(mode int, l, t, tl, tr uint32) uint32 {
	switch mode {
	case 0:
		return 0xff000000
	case 1:
		return l
	case 2:
		return t
	case 3:
		return tr
	case 4:
		return tl
	case 5:
		return average2(average2(l, tr), t)
	case 6:
		return average2(l, tl)
	case 7:
		return average2(l, t)
	case 8:
		return average2(tl, t)
	case 9:
		return average2(t, tr)
	case 10:
		return average2(average2(l, tl), average2(t, tr))
	case 11:
		return selectPredictor(l, t, tl)
	case 12:
		return clampAddSubtractFull(l, t, tl)
	case 13:
		return clampAddSubtractHalf(average2(l, t), tl)
	}
	return 0xff000000
}

func inversePredictor(pix []uint32, t *vp8lTransform, w, h int) {
	bw := divRoundUp(w, 1<<t.bits)
	// first pixel: black predictor; rest of first row: left
	pix[0] = addARGB(pix[0], 0xff000000)
	for x := 1; x < w; x++ {
		pix[x] = addARGB(pix[x], pix[x-1])
	}
	for y := 1; y < h; y++ {
		row := y * w
		pix[row] = addARGB(pix[row], pix[row-w])
		for x := 1; x < w; x++ {
			mode := int(t.data[(y>>t.bits)*bw+(x>>t.bits)]>>8) & 0xf
			l := pix[row+x-1]
			tp := pix[row+x-w]
			tl := pix[row+x-w-1]
			var tr uint32
			if x+1 < w {
				tr = pix[row+x-w+1]
			} else {
				// rightmost column: use the leftmost pixel of the current row
				tr = pix[row]
			}
			pix[row+x] = addARGB(pix[row+x], predict(mode, l, tp, tl, tr))
		}
	}
}

// decodeVP8L decodes a complete VP8L chunk (with header) into an NRGBA image.
func decodeVP8L(chunk []byte) (image.Image, error) {
	if len(chunk) < 5 || chunk[0] != 0x2f {
		return nil, errVP8LInvalid
	}
	br := &lsbBitReader{r: &sliceByteReader{data: chunk[1:]}}
	w := int(br.readBits(14)) + 1
	h := int(br.readBits(14)) + 1
	_ = br.readBits(1) // alpha_is_used hint
	if br.readBits(3) != 0 {
		return nil, errVP8LInvalid
	}
	d := &vp8lDecoder{br: br}
	pix, err := d.decodeImageStream(w, h)
	if err != nil {
		return nil, err
	}
	img := image.NewNRGBA(image.Rect(0, 0, w, h))
	for i, p := range pix {
		img.Pix[i*4+0] = uint8(p >> 16)
		img.Pix[i*4+1] = uint8(p >> 8)
		img.Pix[i*4+2] = uint8(p)
		img.Pix[i*4+3] = uint8(p >> 24)
	}
	return img, nil
}

type sliceByteReader struct {
	data []byte
	pos  int
}

func (s *sliceByteReader) ReadByte() (byte, error) {
	if s.pos >= len(s.data) {
		return 0, io.EOF
	}
	b := s.data[s.pos]
	s.pos++
	return b, nil
}
