// synthetic "photo-like" image: smooth gradients + shapes + noise, optional alpha
func main() {
	w, _ := strconv.Atoi(os.Args[1])
	h, _ := strconv.Atoi(os.Args[2])
	seed, _ := strconv.Atoi(os.Args[3])
	alpha := os.Args[4] == "1"
	r := rand.New(rand.NewSource(int64(seed)))
	m := image.NewNRGBA(image.Rect(0, 0, w, h))
	cx, cy := float64(w)/2, float64(h)/2
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			fx, fy := float64(x), float64(y)
			d := math.Hypot(fx-cx, fy-cy)
			R := 128 + 100*math.Sin(fx/float64(w)*6+float64(seed))
			G := 128 + 100*math.Cos(fy/float64(h)*5)
			B := 128 + 120*math.Sin(d/10)
			if (x/8+y/8)%7 == 0 {
				R, G, B = 255-R, G*0.5, 255-B
			}
			R += float64(r.Intn(21) - 10)
			G += float64(r.Intn(21) - 10)
			B += float64(r.Intn(21) - 10)
			cl := func(v float64) uint8 {
				if v < 0 {
					return 0
				}
				if v > 255 {
					return 255
				}
				return uint8(v)
			}
			a := uint8(255)
			if alpha {
				a = cl(255 - d*255/math.Hypot(cx, cy) + float64(r.Intn(40)))
			}
			m.Set(x, y, color.NRGBA{cl(R), cl(G), cl(B), a})
		}
	}
	f, _ := os.Create(os.Args[5])
	png.Encode(f, m)
	f.Close()
