cd /workspace && cat > src/vp8.go <<'EOF'
package main

import (
	"errors"
	"image"
)

// Decoder for VP8 key frames (RFC 6386) as used by lossy WebP.

var errVP8Invalid = errors.New("vp8: invalid bitstream")
var errVP8Unsupported = errors.New("vp8: unsupported feature")

// boolDecoder is the arithmetic decoder of section 7.
type boolDecoder struct {
	data     []byte
	pos      int
	value    uint32
	rng      uint32
	bitCount int
}

func newBoolDecoder(data []byte) *boolDecoder {
	d := &boolDecoder{data: data, rng: 255}
	for i := 0; i < 2; i++ {
		d.value <<= 8
		if d.pos < len(d.data) {
			d.value |= uint32(d.data[d.pos])
			d.pos++
		}
	}
	return d
}

func (d *boolDecoder) readBool(prob uint8) bool {
	split := 1 + (((d.rng - 1) * uint32(prob)) >> 8)
	bigSplit := split << 8
	var ret bool
	if d.value >= bigSplit {
		ret = true
		d.rng -= split
		d.value -= bigSplit
	} else {
		d.rng = split
	}
	for d.rng < 128 {
		d.value <<= 1
		d.rng <<= 1
		d.bitCount++
		if d.bitCount == 8 {
			d.bitCount = 0
			if d.pos < len(d.data) {
				d.value |= uint32(d.data[d.pos])
				d.pos++
			}
		}
	}
	return ret
}

func (d *boolDecoder) readBit() int {
	if d.readBool(128) {
		return 1
	}
	return 0
}

func (d *boolDecoder) readLiteral(n uint) int {
	v := 0
	for i := uint(0); i < n; i++ {
		v = v<<1 | d.readBit()
	}
	return v
}

// readSigned reads an n-bit magnitude followed by a sign bit.
func (d *boolDecoder) readSigned(n uint) int {
	v := d.readLiteral(n)
	if d.readBit() == 1 {
		return -v
	}
	return v
}

// readOptSigned reads a flag and, when set, a signed value.
func (d *boolDecoder) readOptSigned(n uint) int {
	if d.readBit() == 1 {
		return d.readSigned(n)
	}
	return 0
}

type segmentHeader struct {
	enabled    bool
	updateMap  bool
	absolute   bool
	quant      [4]int
	filter     [4]int
	treeProbs  [3]uint8
}

type filterHeader struct {
	simple      bool
	level       int
	sharpness   int
	adjEnabled  bool
	refDelta    [4]int
	modeDelta   [4]int
}

type quantFactors struct {
	y1 [2]int32 // dc, ac
	y2 [2]int32
	uv [2]int32
}

type macroblock struct {
	yMode    int
	uvMode   int
	bModes   [16]int
	segment  int
	skip     bool // signalled skip flag
	hasCoeff bool // any token decoded
	filter   int  // loop filter level
	inner    bool // filter inner edges
}

type vp8Decoder struct {
	width, height int
	mbW, mbH      int
	seg           segmentHeader
	filt          filterHeader
	quant         [4]quantFactors
	coeffProbs    [4][8][3][11]uint8
	skipProb      uint8
	useSkip       bool
	partitions    []*boolDecoder
	mbs           []macroblock

	// reconstruction buffers (unfiltered) with padding; stride = mbW*16+32
	ybuf, ubuf, vbuf []uint8
	yStride, cStride int

	// non-zero contexts
	aboveNZ    [][9]uint8 // per mb column: 4 y, 2 u, 2 v, 1 y2
	leftNZ     [9]uint8
	aboveModes [][4]int // per mb column: sub-block modes of bottom row
	leftModes  [4]int

	coeffs [25][16]int32 // decoded coefficients for current mb
}

func decodeVP8Frame(chunk []byte) (*image.YCbCr, error) {
	if len(chunk) < 10 {
		return nil, errVP8Invalid
	}
	tag := uint32(chunk[0]) | uint32(chunk[1])<<8 | uint32(chunk[2])<<16
	if tag&1 != 0 {
		return nil, errVP8Unsupported // not a key frame
	}
	version := (tag >> 1) & 7
	if version > 3 {
		return nil, errVP8Unsupported
	}
	firstPartSize := int(tag >> 5)
	if chunk[3] != 0x9d || chunk[4] != 0x01 || chunk[5] != 0x2a {
		return nil, errVP8Invalid
	}
	d := &vp8Decoder{}
	d.width = int(uint16(chunk[6])|uint16(chunk[7])<<8) & 0x3fff
	d.height = int(uint16(chunk[8])|uint16(chunk[9])<<8) & 0x3fff
	if d.width == 0 || d.height == 0 {
		return nil, errVP8Invalid
	}
	rest := chunk[10:]
	if firstPartSize > len(rest) {
		return nil, errVP8Invalid
	}
	hdr := newBoolDecoder(rest[:firstPartSize])
	if err := d.parseHeader(hdr); err != nil {
		return nil, err
	}
	if err := d.setupPartitions(rest[firstPartSize:]); err != nil {
		return nil, err
	}
	d.mbW = (d.width + 15) / 16
	d.mbH = (d.height + 15) / 16
	d.allocate()
	d.decodeMacroblocks(hdr)
	d.loopFilter()
	return d.output(), nil
}

func (d *vp8Decoder) parseHeader(br *boolDecoder) error {
	colorSpace := br.readBit()
	_ = br.readBit() // clamping type
	if colorSpace != 0 {
		return errVP8Unsupported
	}
	// segmentation
	d.seg.enabled = br.readBit() == 1
	if d.seg.enabled {
		d.seg.updateMap = br.readBit() == 1
		updateData := br.readBit() == 1
		if updateData {
			d.seg.absolute = br.readBit() == 1
			for i := 0; i < 4; i++ {
				d.seg.quant[i] = br.readOptSigned(7)
			}
			for i := 0; i < 4; i++ {
				d.seg.filter[i] = br.readOptSigned(6)
			}
		}
		if d.seg.updateMap {
			for i := 0; i < 3; i++ {
				if br.readBit() == 1 {
					d.seg.treeProbs[i] = uint8(br.readLiteral(8))
				} else {
					d.seg.treeProbs[i] = 255
				}
			}
		}
	}
	// loop filter
	d.filt.simple = br.readBit() == 1
	d.filt.level = br.readLiteral(6)
	d.filt.sharpness = br.readLiteral(3)
	d.filt.adjEnabled = br.readBit() == 1
	if d.filt.adjEnabled {
		if br.readBit() == 1 { // mode_ref_lf_delta_update
			for i := 0; i < 4; i++ {
				d.filt.refDelta[i] = br.readOptSigned(6)
			}
			for i := 0; i < 4; i++ {
				d.filt.modeDelta[i] = br.readOptSigned(6)
			}
		}
	}
	// partitions
	nParts := 1 << uint(br.readLiteral(2))
	d.partitions = make([]*boolDecoder, nParts)
	// quantizer indices
	yacQI := br.readLiteral(7)
	ydcDelta := br.readOptSigned(4)
	y2dcDelta := br.readOptSigned(4)
	y2acDelta := br.readOptSigned(4)
	uvdcDelta := br.readOptSigned(4)
	uvacDelta := br.readOptSigned(4)
	for s := 0; s < 4; s++ {
		q := yacQI
		if d.seg.enabled {
			if d.seg.absolute {
				q = d.seg.quant[s]
			} else {
				q += d.seg.quant[s]
			}
		}
		qf := &d.quant[s]
		qf.y1[0] = dcQLookup[clampQ(q+ydcDelta)]
		qf.y1[1] = acQLookup[clampQ(q)]
		qf.y2[0] = dcQLookup[clampQ(q+y2dcDelta)] * 2
		qf.y2[1] = acQLookup[clampQ(q+y2acDelta)] * 155 / 100
		if qf.y2[1] < 8 {
			qf.y2[1] = 8
		}
		qf.uv[0] = dcQLookup[clampQ(q+uvdcDelta)]
		if qf.uv[0] > 132 {
			qf.uv[0] = 132
		}
		qf.uv[1] = acQLookup[clampQ(q+uvacDelta)]
	}
	_ = br.readBit() // refresh_entropy_probs (irrelevant for a single key frame)
	// token probability updates
	d.coeffProbs = defaultCoeffProbs
	for i := 0; i < 4; i++ {
		for j := 0; j < 8; j++ {
			for k := 0; k < 3; k++ {
				for l := 0; l < 11; l++ {
					if br.readBool(coeffUpdateProbs[i][j][k][l]) {
						d.coeffProbs[i][j][k][l] = uint8(br.readLiteral(8))
					}
				}
			}
		}
	}
	d.useSkip = br.readBit() == 1
	if d.useSkip {
		d.skipProb = uint8(br.readLiteral(8))
	}
	return nil
}

func clampQ(q int) int {
	if q < 0 {
		return 0
	}
	if q > 127 {
		return 127
	}
	return q
}

func (d *vp8Decoder) setupPartitions(data []byte) error {
	n := len(d.partitions)
	sizesLen := 3 * (n - 1)
	if len(data) < sizesLen {
		return errVP8Invalid
	}
	sizes := data[:sizesLen]
	data = data[sizesLen:]
	for i := 0; i < n; i++ {
		var sz int
		if i < n-1 {
			sz = int(sizes[i*3]) | int(sizes[i*3+1])<<8 | int(sizes[i*3+2])<<16
			if sz > len(data) {
				return errVP8Invalid
			}
		} else {
			sz = len(data)
		}
		d.partitions[i] = newBoolDecoder(data[:sz])
		data = data[sz:]
	}
	return nil
}

func (d *vp8Decoder) allocate() {
	d.yStride = d.mbW*16 + 32
	d.cStride = d.mbW*8 + 16
	d.ybuf = make([]uint8, d.yStride*(d.mbH*16+16))
	d.ubuf = make([]uint8, d.cStride*(d.mbH*8+8))
	d.vbuf = make([]uint8, d.cStride*(d.mbH*8+8))
	d.mbs = make([]macroblock, d.mbW*d.mbH)
	d.aboveNZ = make([][9]uint8, d.mbW)
	d.aboveModes = make([][4]int, d.mbW)
}

// pixel offsets: luma pixel (x, y) of the frame lives at (y+16)*yStride + x + 16
func (d *vp8Decoder) yOff(x, y int) int { return (y+16)*d.yStride + x + 16 }
func (d *vp8Decoder) cOff(x, y int) int { return (y+8)*d.cStride + x + 8 }

func (d *vp8Decoder) decodeMacroblocks(hdr *boolDecoder) {
	for mby := 0; mby < d.mbH; mby++ {
		tokens := d.partitions[mby%len(d.partitions)]
		d.leftNZ = [9]uint8{}
		d.leftModes = [4]int{bDCPred, bDCPred, bDCPred, bDCPred}
		for mbx := 0; mbx < d.mbW; mbx++ {
			mb := &d.mbs[mby*d.mbW+mbx]
			d.parseModes(hdr, mb, mbx)
			d.parseResiduals(tokens, mb, mbx)
			d.reconstruct(mb, mbx, mby)
		}
	}
}

func (d *vp8Decoder) parseModes(br *boolDecoder, mb *macroblock, mbx int) {
	if d.seg.updateMap {
		if br.readBool(d.seg.treeProbs[0]) {
			mb.segment = 2 + boolToInt(br.readBool(d.seg.treeProbs[2]))
		} else {
			mb.segment = boolToInt(br.readBool(d.seg.treeProbs[1]))
		}
	}
	if d.useSkip {
		mb.skip = br.readBool(d.skipProb)
	}
	// luma mode
	if !br.readBool(kfYModeProb[0]) {
		mb.yMode = bPred
		above := &d.aboveModes[mbx]
		for i := 0; i < 16; i++ {
			var a, l int
			if i < 4 {
				a = above[i]
			} else {
				a = mb.bModes[i-4]
			}
			if i&3 == 0 {
				l = d.leftModes[i>>2]
			} else {
				l = mb.bModes[i-1]
			}
			mb.bModes[i] = readBMode(br, &kfBModeProb[a][l])
		}
	} else {
		if !br.readBool(kfYModeProb[1]) {
			if !br.readBool(kfYModeProb[2]) {
				mb.yMode = dcPred
			} else {
				mb.yMode = vPred
			}
		} else {
			if !br.readBool(kfYModeProb[3]) {
				mb.yMode = hPred
			} else {
				mb.yMode = tmPred
			}
		}
		implied := impliedBMode(mb.yMode)
		for i := range mb.bModes {
			mb.bModes[i] = implied
		}
	}
	// chroma mode
	if !br.readBool(kfUVModeProb[0]) {
		mb.uvMode = dcPred
	} else if !br.readBool(kfUVModeProb[1]) {
		mb.uvMode = vPred
	} else if !br.readBool(kfUVModeProb[2]) {
		mb.uvMode = hPred
	} else {
		mb.uvMode = tmPred
	}
	// update mode contexts
	for i := 0; i < 4; i++ {
		d.aboveModes[mbx][i] = mb.bModes[12+i]
		d.leftModes[i] = mb.bModes[i*4+3]
	}
}

func boolToInt(b bool) int {
	if b {
		return 1
	}
	return 0
}

func impliedBMode(yMode int) int {
	switch yMode {
	case vPred:
		return bVEPred
	case hPred:
		return bHEPred
	case tmPred:
		return bTMPred
	}
	return bDCPred
}

// readBMode walks the sub-block mode tree.
func readBMode(br *boolDecoder, p *[numBModes - 1]uint8) int {
	if !br.readBool(p[0]) {
		return bDCPred
	}
	if !br.readBool(p[1]) {
		return bTMPred
	}
	if !br.readBool(p[2]) {
		return bVEPred
	}
	if !br.readBool(p[3]) {
		if !br.readBool(p[4]) {
			return bHEPred
		}
		if !br.readBool(p[5]) {
			return bRDPred
		}
		return bVRPred
	}
	if !br.readBool(p[6]) {
		return bLDPred
	}
	if !br.readBool(p[7]) {
		return bVLPred
	}
	if !br.readBool(p[8]) {
		return bHDPred
	}
	return bHUPred
}

// readCoefficients decodes one 4x4 block of tokens. It returns the index
// after the last decoded token (0 when the first token is EOB).
func (d *vp8Decoder) readCoefficients(br *boolDecoder, plane int, ctx int, first int, dq [2]int32, out *[16]int32) int {
	probs := &d.coeffProbs[plane]
	i := first
	p := &probs[coeffBands[i]][ctx]
	if !br.readBool(p[0]) {
		return 0
	}
	for i < 16 {
		if !br.readBool(p[1]) {
			// zero token: next token cannot be EOB
			i++
			if i == 16 {
				return 16
			}
			p = &probs[coeffBands[i]][0]
			continue
		}
		var v int32
		nextCtx := 2
		if !br.readBool(p[2]) {
			v = 1
			nextCtx = 1
		} else if !br.readBool(p[3]) {
			if !br.readBool(p[4]) {
				v = 2
			} else {
				v = 3 + int32(boolToInt(br.readBool(p[5])))
			}
		} else if !br.readBool(p[6]) {
			if !br.readBool(p[7]) {
				v = 5 + readExtra(br, pcat1)
			} else {
				v = 7 + readExtra(br, pcat2)
			}
		} else if !br.readBool(p[8]) {
			if !br.readBool(p[9]) {
				v = 11 + readExtra(br, pcat3)
			} else {
				v = 19 + readExtra(br, pcat4)
			}
		} else if !br.readBool(p[10]) {
			v = 35 + readExtra(br, pcat5)
		} else {
			v = 67 + readExtra(br, pcat6)
		}
		if br.readBit() == 1 {
			v = -v
		}
		q := dq[1]
		if i == 0 {
			q = dq[0]
		}
		out[zigzag[i]] = v * q
		i++
		if i == 16 {
			return 16
		}
		p = &probs[coeffBands[i]][nextCtx]
		if !br.readBool(p[0]) {
			return i
		}
	}
	return 16
}

func readExtra(br *boolDecoder, probs []uint8) int32 {
	var v int32
	for _, p := range probs {
		v = v<<1 | int32(boolToInt(br.readBool(p)))
	}
	return v
}

func (d *vp8Decoder) parseResiduals(br *boolDecoder, mb *macroblock, mbx int) {
	for i := range d.coeffs {
		d.coeffs[i] = [16]int32{}
	}
	above := &d.aboveNZ[mbx]
	left := &d.leftNZ
	if mb.skip {
		for i := 0; i < 8; i++ {
			above[i] = 0
			left[i] = 0
		}
		if mb.yMode != bPred {
			above[8] = 0
			left[8] = 0
		}
		mb.hasCoeff = false
		return
	}
	qf := &d.quant[mb.segment]
	first := 0
	plane := 3
	any := false
	if mb.yMode != bPred {
		// Y2 block
		ctx := int(above[8] + left[8])
		var y2 [16]int32
		n := d.readCoefficients(br, 1, ctx, 0, qf.y2, &y2)
		nz := uint8(boolToInt(n > 0))
		above[8], left[8] = nz, nz
		if n > 0 {
			any = true
		}
		inverseWHT(&y2, &d.coeffs)
		first = 1
		plane = 0
	}
	for y := 0; y < 4; y++ {
		for x := 0; x < 4; x++ {
			ctx := int(above[x] + left[y])
			n := d.readCoefficients(br, plane, ctx, first, qf.y1, &d.coeffs[y*4+x])
			nz := uint8(boolToInt(n > first))
			above[x], left[y] = nz, nz
			if n > first {
				any = true
			}
		}
	}
	// chroma: U blocks 16..19, V blocks 20..23
	for c := 0; c < 2; c++ {
		for y := 0; y < 2; y++ {
			for x := 0; x < 2; x++ {
				ai := 4 + c*2 + x
				li := 4 + c*2 + y
				ctx := int(above[ai] + left[li])
				n := d.readCoefficients(br, 2, ctx, 0, qf.uv, &d.coeffs[16+c*4+y*2+x])
				nz := uint8(boolToInt(n > 0))
				above[ai], left[li] = nz, nz
				if n > 0 {
					any = true
				}
			}
		}
	}
	mb.hasCoeff = any
}

// inverseWHT distributes the second-order DC values to the 16 luma blocks.
func inverseWHT(in *[16]int32, out *[25][16]int32) {
	var tmp [16]int32
	for i := 0; i < 4; i++ {
		a1 := in[i] + in[12+i]
		b1 := in[4+i] + in[8+i]
		c1 := in[4+i] - in[8+i]
		d1 := in[i] - in[12+i]
		tmp[i] = a1 + b1
		tmp[4+i] = c1 + d1
		tmp[8+i] = a1 - b1
		tmp[12+i] = d1 - c1
	}
	for i := 0; i < 4; i++ {
		a1 := tmp[4*i] + tmp[4*i+3]
		b1 := tmp[4*i+1] + tmp[4*i+2]
		c1 := tmp[4*i+1] - tmp[4*i+2]
		d1 := tmp[4*i] - tmp[4*i+3]
		a2 := a1 + b1
		b2 := c1 + d1
		c2 := a1 - b1
		d2 := d1 - c1
		out[4*i][0] = (a2 + 3) >> 3
		out[4*i+1][0] = (b2 + 3) >> 3
		out[4*i+2][0] = (c2 + 3) >> 3
		out[4*i+3][0] = (d2 + 3) >> 3
	}
}

const (
	cospi8sqrt2minus1 = 20091
	sinpi8sqrt2       = 35468
)

// inverseDCT adds the inverse transform of in to the 4x4 block at buf[off].
func inverseDCT(in *[16]int32, buf []uint8, off, stride int) {
	var tmp [16]int32
	for i := 0; i < 4; i++ {
		a1 := in[i] + in[8+i]
		b1 := in[i] - in[8+i]
		t1 := (in[4+i] * sinpi8sqrt2) >> 16
		t2 := in[12+i] + ((in[12+i] * cospi8sqrt2minus1) >> 16)
		c1 := t1 - t2
		t1 = in[4+i] + ((in[4+i] * cospi8sqrt2minus1) >> 16)
		t2 = (in[12+i] * sinpi8sqrt2) >> 16
		d1 := t1 + t2
		tmp[i] = a1 + d1
		tmp[12+i] = a1 - d1
		tmp[4+i] = b1 + c1
		tmp[8+i] = b1 - c1
	}
	for i := 0; i < 4; i++ {
		a1 := tmp[4*i] + tmp[4*i+2]
		b1 := tmp[4*i] - tmp[4*i+2]
		t1 := (tmp[4*i+1] * sinpi8sqrt2) >> 16
		t2 := tmp[4*i+3] + ((tmp[4*i+3] * cospi8sqrt2minus1) >> 16)
		c1 := t1 - t2
		t1 = tmp[4*i+1] + ((tmp[4*i+1] * cospi8sqrt2minus1) >> 16)
		t2 = (tmp[4*i+3] * sinpi8sqrt2) >> 16
		d1 := t1 + t2
		row := off + i*stride
		buf[row+0] = clampPix(int32(buf[row+0]) + ((a1 + d1 + 4) >> 3))
		buf[row+3] = clampPix(int32(buf[row+3]) + ((a1 - d1 + 4) >> 3))
		buf[row+1] = clampPix(int32(buf[row+1]) + ((b1 + c1 + 4) >> 3))
		buf[row+2] = clampPix(int32(buf[row+2]) + ((b1 - c1 + 4) >> 3))
	}
}

func clampPix(v int32) uint8 {
	if v < 0 {
		return 0
	}
	if v > 255 {
		return 255
	}
	return uint8(v)
}

// reconstruct performs intra prediction and adds the residual.
func (d *vp8Decoder) reconstruct(mb *macroblock, mbx, mby int) {
	// --- luma ---
	yo := d.yOff(mbx*16, mby*16)
	ys := d.yStride
	d.prepareEdges(mbx, mby)
	if mb.yMode == bPred {
		for i := 0; i < 16; i++ {
			bx, by := i&3, i>>2
			off := yo + by*4*ys + bx*4
			predictSubblock(d.ybuf, off, ys, mb.bModes[i], d.aboveRight(mbx, mby, by, bx))
			inverseDCT(&d.coeffs[i], d.ybuf, off, ys)
		}
	} else {
		predictMacroblock(d.ybuf, yo, ys, 16, mb.yMode, mbx > 0, mby > 0)
		for i := 0; i < 16; i++ {
			bx, by := i&3, i>>2
			inverseDCT(&d.coeffs[i], d.ybuf, yo+by*4*ys+bx*4, ys)
		}
	}
	// --- chroma ---
	cs := d.cStride
	for c := 0; c < 2; c++ {
		buf := d.ubuf
		if c == 1 {
			buf = d.vbuf
		}
		co := d.cOff(mbx*8, mby*8)
		predictMacroblock(buf, co, cs, 8, mb.uvMode, mbx > 0, mby > 0)
		for i := 0; i < 4; i++ {
			bx, by := i&1, i>>1
			inverseDCT(&d.coeffs[16+c*4+i], buf, co+by*4*cs+bx*4, cs)
		}
	}
}

// prepareEdges fills the synthetic border pixels (127 above, 129 left)
// for macroblocks on the frame boundary.
func (d *vp8Decoder) prepareEdges(mbx, mby int) {
	ys, cs := d.yStride, d.cStride
	yo := d.yOff(mbx*16, mby*16)
	co := d.cOff(mbx*8, mby*8)
	if mby == 0 {
		for x := -1; x < 16+4; x++ {
			d.ybuf[yo-ys+x] = 127
		}
		for x := -1; x < 8; x++ {
			d.ubuf[co-cs+x] = 127
			d.vbuf[co-cs+x] = 127
		}
	}
	if mbx == 0 {
		for y := 0; y < 16; y++ {
			d.ybuf[yo+y*ys-1] = 129
		}
		for y := 0; y < 8; y++ {
			d.ubuf[co+y*cs-1] = 129
			d.vbuf[co+y*cs-1] = 129
		}
		if mby > 0 {
			d.ybuf[yo-ys-1] = 129
			d.ubuf[co-cs-1] = 129
			d.vbuf[co-cs-1] = 129
		}
	}
}

// aboveRight returns the four pixels above and to the right of sub-block
// (bx, by); they always come from the macroblock row above.
func (d *vp8Decoder) aboveRight(mbx, mby, by, bx int) [4]uint8 {
	ys := d.yStride
	yo := d.yOff(mbx*16, mby*16)
	var ar [4]uint8
	if bx < 3 {
		// above-right pixels are inside this macroblock (or the row above)
		off := yo + (by*4-1)*ys + bx*4 + 4
		copy(ar[:], d.ybuf[off:off+4])
		return ar
	}
	// rightmost column: pixels from the macroblock above-right
	if mby == 0 {
		return [4]uint8{127, 127, 127, 127}
	}
	if mbx == d.mbW-1 {
		v := d.ybuf[yo-ys+15]
		return [4]uint8{v, v, v, v}
	}
	off := yo - ys + 16
	copy(ar[:], d.ybuf[off:off+4])
	return ar
}

// predictMacroblock fills an n x n block using the whole-block modes.
func predictMacroblock(buf []uint8, off, stride, n, mode int, haveLeft, haveAbove bool) {
	switch mode {
	case dcPred:
		sum := 0
		shift := 3
		if n == 16 {
			shift = 4
		}
		count := 0
		if haveAbove {
			for x := 0; x < n; x++ {
				sum += int(buf[off-stride+x])
			}
			count++
		}
		if haveLeft {
			for y := 0; y < n; y++ {
				sum += int(buf[off+y*stride-1])
			}
			count++
		}
		v := uint8(128)
		switch count {
		case 2:
			v = uint8((sum + (1 << uint(shift))) >> uint(shift+1))
		case 1:
			v = uint8((sum + (1 << uint(shift-1))) >> uint(shift))
		}
		for y := 0; y < n; y++ {
			for x := 0; x < n; x++ {
				buf[off+y*stride+x] = v
			}
		}
	case vPred:
		for y := 0; y < n; y++ {
			copy(buf[off+y*stride:off+y*stride+n], buf[off-stride:off-stride+n])
		}
	case hPred:
		for y := 0; y < n; y++ {
			v := buf[off+y*stride-1]
			for x := 0; x < n; x++ {
				buf[off+y*stride+x] = v
			}
		}
	case tmPred:
		p := int32(buf[off-stride-1])
		for y := 0; y < n; y++ {
			l := int32(buf[off+y*stride-1])
			for x := 0; x < n; x++ {
				buf[off+y*stride+x] = clampPix(l + int32(buf[off-stride+x]) - p)
			}
		}
	}
}

func avg2(a, b uint8) uint8 {
	return uint8((int(a) + int(b) + 1) >> 1)
}

func avg3(a, b, c uint8) uint8 {
	return uint8((int(a) + 2*int(b) + int(c) + 2) >> 2)
}

// predictSubblock fills a 4x4 block according to one of the ten sub-block
// modes, using the pixels above (A, with the above-right extension), to
// the left (L) and the corner (P).
func predictSubblock(buf []uint8, off, stride, mode int, aboveRight [4]uint8) {
	var A [8]uint8
	var L [4]uint8
	for i := 0; i < 4; i++ {
		A[i] = buf[off-stride+i]
		A[4+i] = aboveRight[i]
		L[i] = buf[off+i*stride-1]
	}
	P := buf[off-stride-1]
	set := func(x, y int, v uint8) { buf[off+y*stride+x] = v }
	switch mode {
	case bDCPred:
		sum := 4
		for i := 0; i < 4; i++ {
			sum += int(A[i]) + int(L[i])
		}
		v := uint8(sum >> 3)
		for y := 0; y < 4; y++ {
			for x := 0; x < 4; x++ {
				set(x, y, v)
			}
		}
	case bTMPred:
		for y := 0; y < 4; y++ {
			for x := 0; x < 4; x++ {
				set(x, y, clampPix(int32(L[y])+int32(A[x])-int32(P)))
			}
		}
	case bVEPred:
		for x := 0; x < 4; x++ {
			var left uint8
			if x == 0 {
				left = P
			} else {
				left = A[x-1]
			}
			v := avg3(left, A[x], A[x+1])
			for y := 0; y < 4; y++ {
				set(x, y, v)
			}
		}
	case bHEPred:
		for y := 0; y < 4; y++ {
			var up, down uint8
			if y == 0 {
				up = P
			} else {
				up = L[y-1]
			}
			if y == 3 {
				down = L[3]
			} else {
				down = L[y+1]
			}
			v := avg3(up, L[y], down)
			for x := 0; x < 4; x++ {
				set(x, y, v)
			}
		}
	case bLDPred:
		for y := 0; y < 4; y++ {
			for x := 0; x < 4; x++ {
				i := x + y
				if i < 6 {
					set(x, y, avg3(A[i], A[i+1], A[i+2]))
				} else {
					set(x, y, avg3(A[6], A[7], A[7]))
				}
			}
		}
	case bRDPred:
		// edge: E[0..8] = L3, L2, L1, L0, P, A0, A1, A2, A3
		E := [9]uint8{L[3], L[2], L[1], L[0], P, A[0], A[1], A[2], A[3]}
		for y := 0; y < 4; y++ {
			for x := 0; x < 4; x++ {
				i := 3 - y + x
				set(x, y, avg3(E[i], E[i+1], E[i+2]))
			}
		}
	case bVRPred:
		E := [9]uint8{L[3], L[2], L[1], L[0], P, A[0], A[1], A[2], A[3]}
		set(0, 3, avg3(E[1], E[2], E[3]))
		set(0, 2, avg3(E[2], E[3], E[4]))
		set(1, 3, avg3(E[3], E[4], E[5]))
		set(0, 1, avg3(E[3], E[4], E[5]))
		set(1, 2, avg2(E[4], E[5]))
		set(0, 0, avg2(E[4], E[5]))
		set(2, 3, avg3(E[4], E[5], E[6]))
		set(1, 1, avg3(E[4], E[5], E[6]))
		set(2, 2, avg2(E[5], E[6]))
		set(1, 0, avg2(E[5], E[6]))
		set(3, 3, avg3(E[5], E[6], E[7]))
		set(2, 1, avg3(E[5], E[6], E[7]))
		set(3, 2, avg2(E[6], E[7]))
		set(2, 0, avg2(E[6], E[7]))
		set(3, 1, avg3(E[6], E[7], E[8]))
		set(3, 0, avg2(E[7], E[8]))
	case bVLPred:
		set(0, 0, avg2(A[0], A[1]))
		set(0, 1, avg3(A[0], A[1], A[2]))
		set(0, 2, avg2(A[1], A[2]))
		set(1, 0, avg2(A[1], A[2]))
		set(1, 1, avg3(A[1], A[2], A[3]))
		set(0, 3, avg3(A[1], A[2], A[3]))
		set(1, 2, avg2(A[2], A[3]))
		set(2, 0, avg2(A[2], A[3]))
		set(1, 3, avg3(A[2], A[3], A[4]))
		set(2, 1, avg3(A[2], A[3], A[4]))
		set(2, 2, avg2(A[3], A[4]))
		set(3, 0, avg2(A[3], A[4]))
		set(2, 3, avg3(A[3], A[4], A[5]))
		set(3, 1, avg3(A[3], A[4], A[5]))
		set(3, 2, avg3(A[4], A[5], A[6]))
		set(3, 3, avg3(A[5], A[6], A[7]))
	case bHDPred:
		E := [9]uint8{L[3], L[2], L[1], L[0], P, A[0], A[1], A[2], A[3]}
		set(0, 3, avg2(E[0], E[1]))
		set(1, 3, avg3(E[0], E[1], E[2]))
		set(0, 2, avg2(E[1], E[2]))
		set(2, 3, avg2(E[1], E[2]))
		set(1, 2, avg3(E[1], E[2], E[3]))
		set(3, 3, avg3(E[1], E[2], E[3]))
		set(2, 2, avg2(E[2], E[3]))
		set(0, 1, avg2(E[2], E[3]))
		set(3, 2, avg3(E[2], E[3], E[4]))
		set(1, 1, avg3(E[2], E[3], E[4]))
		set(2, 1, avg2(E[3], E[4]))
		set(0, 0, avg2(E[3], E[4]))
		set(3, 1, avg3(E[3], E[4], E[5]))
		set(1, 0, avg3(E[3], E[4], E[5]))
		set(2, 0, avg3(E[4], E[5], E[6]))
		set(3, 0, avg3(E[5], E[6], E[7]))
	case bHUPred:
